window.CURSOS_MARA = window.CURSOS_MARA || [];
window.CURSOS_MARA.push({"id":"diplomado-persuasion-etica","nombre":"Diplomado en Técnicas de Persuasión y Comunicación Ética","idioma":"es-MX","color":"#6c24dd","nivel":"Diplomado","familia":"Diplomados","periodoTipo":"Módulo","periodoNum":10,"desc":"Argumentar con evidencia, escuchar y comunicar propuestas con respeto a la autonomía.","horas":60,"precio":2490,"publicado":true,"proximamente":false,"modulos":[{"id":"pe-m01","titulo":"Persuasión ética y decisiones informadas","resumen":"Audita tres mensajes ficticios: una invitación comunitaria, una oferta de servicio y una solicitud a un equipo. Señala qué se pide, qué evidencia existe, qué información falta y cómo se puede rechazar. Reescribe uno y explica tus cambios.","lecciones":[{"id":"pe-m01-l1","titulo":"Decidir libremente","objetivo":"Aplicar decidir libremente mediante un caso, una decisión comentada y una producción propia.","bloques":[{"tipo":"imagen","url":"recursos/diplomado-persuasion-etica/visuales/pe-m01.svg","pie":"Mapa del módulo: Decidir libremente; Intención, transparencia y consecuencias; Urgencia real y presión artificial; Auditar un mensaje completo"},{"tipo":"texto","texto":"<p>Persuadir es presentar razones para que alguien considere una idea o una acción. No significa garantizar un sí. Una persona puede comprender perfectamente tu propuesta y concluir que no le conviene. Evalúa tanto la claridad del intercambio como el resultado: ¿se entendió la acción?, ¿hubo preguntas?, ¿se pudieron examinar las razones?</p><p>Una recomendación puede ser entusiasta y respetuosa. El problema aparece cuando reemplazas razones por amenazas, ocultas condiciones relevantes o conviertes el rechazo en una descalificación personal. No necesitas adivinar intenciones para revisar esas conductas observables.</p><p>Antes de escribir, completa cuatro frases: propongo que…, lo recomiendo porque…, implica dedicar o pagar…, puedes elegir…. Después busca una condición que podría cambiar la decisión de la otra persona. Si existe, inclúyela. La comunicación ética no consiste en añadir una frase amable a una oferta incompleta; consiste en hacer comprensible la decisión real.</p>"},{"tipo":"tarjetas","rotulo":"Guía activa del módulo · anticipa, compara y repasa","voz":false,"tarjetas":[{"frente":"¿Cómo aplicarías «Decidir libremente»? Piensa en una acción concreta antes de voltear.","reverso":"Ejemplo: «Propongo probar una agenda durante dos reuniones. Prepararla requiere diez minutos por persona. Si ese tiempo no cabe en tu turno, revisemos otra forma de recoger temas. Al terminar compararemos duración y acuerdos». El ejemplo especifica una prueba; no promete que toda reunión mejorará.","ej":"Al terminar el módulo, vuelve a esta tarjeta y formula tu propio ejemplo."},{"frente":"¿Cómo aplicarías «Intención, transparencia y consecuencias»? Piensa en una acción concreta antes de voltear.","reverso":"Modelo: «Recibo una comisión si contratas. Usé el plan básico durante dos semanas; no comprobé su seguridad empresarial. Para documentos confidenciales, primero revisaría las condiciones con quien administra tus sistemas». La limitación es específica y permite cambiar la decisión.","ej":"Al terminar el módulo, vuelve a esta tarjeta y formula tu propio ejemplo."},{"frente":"¿Cómo aplicarías «Urgencia real y presión artificial»? Piensa en una acción concreta antes de voltear.","reverso":"Modelo: «Cerramos el jueves para preparar los materiales. Puedes solicitar aviso de la siguiente edición». No se promete una fecha futura que aún no está confirmada. El motivo y la alternativa reducen ambigüedad sin eliminar la decisión.","ej":"Al terminar el módulo, vuelve a esta tarjeta y formula tu propio ejemplo."},{"frente":"¿Cómo aplicarías «Auditar un mensaje completo»? Piensa en una acción concreta antes de voltear.","reverso":"Modelo: para «garantizado», pedir el objeto de la garantía; para «$80 al día», mostrar precio total y permanencia. La versión revisada no debe convertir una garantía de acceso en una promesa de aprendizaje individual.","ej":"Al terminar el módulo, vuelve a esta tarjeta y formula tu propio ejemplo."}]},{"tipo":"destacado","texto":"Caso ficticio: Luis propone que el equipo pruebe una agenda de reuniones. Una compañera no dispone de tiempo para preparar documentos la noche anterior."},{"tipo":"practica","rotulo":"Decide y contrasta","preguntas":[{"p":"¿Qué respuesta ayuda a decidir?","ops":["Explicar el esfuerzo requerido y preguntar qué adaptación sería viable.","Decir que quien quiere mejorar siempre encuentra tiempo.","Pedir un sí ahora y explicar el esfuerzo después."],"correcta":0,"explica":"La respuesta útil aborda la restricción. Las otras alternativas juzgan a la persona u ocultan una condición antes de obtener aceptación.","pista":"Revisa la restricción del caso y el efecto de tu respuesta sobre la decisión de la otra persona."}]},{"tipo":"completar","rotulo":"Recupera la idea clave","items":[{"frase":"Una propuesta debe permitir aceptar o ___ sin descalificaciones.","resp":["rechazar"],"explica":"Relaciona este concepto con la decisión que acabas de analizar."}]},{"tipo":"reflexion","rotulo":"Práctica aplicada · 20 minutos orientativos","pregunta":"Escribe una invitación de 100 palabras a una actividad ficticia. Incluye acción, razón, esfuerzo y libertad de decisión. Luego señala una información que inicialmente omitiste.","ayuda":"Primera versión, contraste con el modelo y revisión propia."},{"tipo":"texto","texto":"<details><summary>Consultar modelo y retroalimentación</summary><p>Ejemplo: «Propongo probar una agenda durante dos reuniones. Prepararla requiere diez minutos por persona. Si ese tiempo no cabe en tu turno, revisemos otra forma de recoger temas. Al terminar compararemos duración y acuerdos». El ejemplo especifica una prueba; no promete que toda reunión mejorará.</p><p>Compara tu respuesta: identifica una condición explícita, una afirmación que necesita respaldo y una mejora concreta. El modelo es una posibilidad, no la única respuesta válida.</p></details>"},{"tipo":"texto","texto":"<p><a href=\"recursos/diplomado-persuasion-etica/cuaderno.md\" download>Descargar cuaderno de trabajo</a></p><p>60 horas estimadas de estudio y práctica; modalidad autogestiva con modelos de respuesta y autoevaluación.</p>"}],"minutosEstimados":45},{"id":"pe-m01-l2","titulo":"Intención, transparencia y consecuencias","objetivo":"Aplicar intención, transparencia y consecuencias mediante un caso, una decisión comentada y una producción propia.","bloques":[{"tipo":"texto","texto":"<p>Una buena intención no vuelve correcta cualquier táctica. Puedes querer que un amigo estudie y, al mismo tiempo, exagerar las consecuencias de no tomar tu curso. Separa el objetivo que persigues de los medios que utilizas y de sus efectos previsibles.</p><p>La transparencia incluye informar de intereses que podrían influir en tu recomendación. Si recibes una comisión, decirlo permite interpretar tu consejo. Esa declaración no convierte automáticamente la recomendación en buena: todavía debes justificar su pertinencia y explicar sus límites.</p><p>Haz una revisión en tres columnas: qué gano yo, qué gana o arriesga la otra persona, qué datos cambiarían nuestra decisión. Añade efectos indirectos: tiempo de terceros, presupuesto compartido o expectativas creadas. No es necesario conocer todas las consecuencias para actuar; sí reconocer incertidumbre y evitar presentar una apuesta como certeza. Cuando tus intereses y los del interlocutor chocan, describe el conflicto en lugar de esconderlo detrás de lenguaje técnico.</p>"},{"tipo":"destacado","texto":"Caso ficticio: Paula recomienda una plataforma y recibe una comisión por cada alta. Ha probado sólo el plan básico."},{"tipo":"practica","rotulo":"Decide y contrasta","preguntas":[{"p":"¿Qué debe aclarar Paula?","ops":["Sólo las funciones que le gustaron, porque la comisión no cambia esas funciones.","Que el producto es el mejor para cualquiera, porque ella lo utiliza.","Que recibe comisión, qué plan probó y qué aspectos no ha evaluado."],"correcta":2,"explica":"Explicar el incentivo y el alcance de la experiencia permite valorar la recomendación. La experiencia personal no demuestra conveniencia universal.","pista":"Revisa la restricción del caso y el efecto de tu respuesta sobre la decisión de la otra persona."}]},{"tipo":"completar","rotulo":"Recupera la idea clave","items":[{"frase":"Un incentivo económico por recomendar es un posible conflicto de ___.","resp":["interés"],"explica":"Relaciona este concepto con la decisión que acabas de analizar."}]},{"tipo":"reflexion","rotulo":"Práctica aplicada · 20 minutos orientativos","pregunta":"Diseña una recomendación de herramienta con una comisión ficticia. Escribe qué revelarías, qué comprobarías y en qué circunstancias no la recomendarías.","ayuda":"Primera versión, contraste con el modelo y revisión propia."},{"tipo":"texto","texto":"<details><summary>Consultar modelo y retroalimentación</summary><p>Modelo: «Recibo una comisión si contratas. Usé el plan básico durante dos semanas; no comprobé su seguridad empresarial. Para documentos confidenciales, primero revisaría las condiciones con quien administra tus sistemas». La limitación es específica y permite cambiar la decisión.</p><p>Compara tu respuesta: identifica una condición explícita, una afirmación que necesita respaldo y una mejora concreta. El modelo es una posibilidad, no la única respuesta válida.</p></details>"},{"tipo":"relacionar","rotulo":"Relaciona el concepto con su aplicación","voz":false,"pares":[["Transparencia","Explicar qué obtienes si aceptan tu propuesta"],["Autonomía","Aceptar una negativa sin castigarla"],["Presión artificial","Inventar un plazo que no existe"],["Condición relevante","Informar el tiempo de preparación necesario"]]},{"tipo":"texto","texto":"<p><strong>Contrasta tu razonamiento:</strong> después de relacionar, explica por qué cada ejemplo corresponde a ese concepto y escribe un contraejemplo. No basta memorizar la pareja: identifica la conducta observable que la distingue.</p>"}],"minutosEstimados":45},{"id":"pe-m01-l3","titulo":"Urgencia real y presión artificial","objetivo":"Aplicar urgencia real y presión artificial mediante un caso, una decisión comentada y una producción propia.","bloques":[{"tipo":"texto","texto":"<p>Una fecha límite puede ser información útil. Un salón tiene capacidad finita y una actividad requiere preparar materiales. El problema no es el plazo en sí, sino afirmar restricciones que no existen o reiniciar una supuesta última oportunidad cada vez que una persona regresa.</p><p>Revisa tres elementos: hecho verificable, consecuencia real y alternativa. «Cerramos inscripciones el jueves porque el viernes se preparan los equipos» explica el motivo. «Compra ahora o perderás tu única oportunidad de cambiar» mezcla una compra con una predicción desproporcionada.</p><p>La escasez no reemplaza la conveniencia. Aunque queden pocos lugares, el participante necesita revisar horario, costo y requisitos. Cuando una decisión tiene consecuencias importantes, evita utilizar la rapidez como prueba de compromiso. Si no sabes cuántos lugares quedan, dilo; no inventes un contador. Al evaluar un mensaje ajeno, pide aclaraciones concretas sin asumir automáticamente que todo plazo es engañoso.</p>"},{"tipo":"destacado","texto":"Caso ficticio: un taller admite veinte participantes porque habrá revisión individual. Ya se inscribieron diecisiete."},{"tipo":"practica","rotulo":"Decide y contrasta","preguntas":[{"p":"¿Qué mensaje refleja la situación?","ops":["Sólo hoy, aunque el mismo precio seguirá disponible el resto del mes.","Quedan tres lugares para esta edición; revisa horarios y condiciones antes de inscribirte.","Si no compras hoy, nunca aprenderás esta habilidad."],"correcta":1,"explica":"La primera opción comunica capacidad real sin asegurar que comprar sea conveniente. Las otras crean consecuencias o restricciones que el caso no respalda.","pista":"Revisa la restricción del caso y el efecto de tu respuesta sobre la decisión de la otra persona."}]},{"tipo":"completar","rotulo":"Recupera la idea clave","items":[{"frase":"Una fecha límite se debe apoyar en una restricción ___.","resp":["real"],"explica":"Relaciona este concepto con la decisión que acabas de analizar."}]},{"tipo":"reflexion","rotulo":"Práctica aplicada · 20 minutos orientativos","pregunta":"Redacta dos avisos de cierre: uno por cupo y otro por logística. Añade una alternativa para quien no pueda decidir a tiempo.","ayuda":"Primera versión, contraste con el modelo y revisión propia."},{"tipo":"texto","texto":"<details><summary>Consultar modelo y retroalimentación</summary><p>Modelo: «Cerramos el jueves para preparar los materiales. Puedes solicitar aviso de la siguiente edición». No se promete una fecha futura que aún no está confirmada. El motivo y la alternativa reducen ambigüedad sin eliminar la decisión.</p><p>Compara tu respuesta: identifica una condición explícita, una afirmación que necesita respaldo y una mejora concreta. El modelo es una posibilidad, no la única respuesta válida.</p></details>"}],"minutosEstimados":45},{"id":"pe-m01-l4","titulo":"Auditar un mensaje completo","objetivo":"Aplicar auditar un mensaje completo mediante un caso, una decisión comentada y una producción propia.","bloques":[{"tipo":"texto","texto":"<p>No revises una propuesta sólo frase por frase. Una frase puede ser cierta y la impresión general resultar engañosa. «Menos de cien pesos al día» podría ocultar un contrato anual. «Miles de usuarios» no explica si esas personas lograron el resultado que te interesa.</p><p>La auditoría empieza identificando la decisión que el mensaje busca. Después separa hechos, interpretaciones, promesas y omisiones. Para cada promesa escribe qué evidencia la sostendría y qué condiciones la limitarían. Evalúa también la llamada a la acción: ¿pide información, una prueba o un pago?, ¿están claras sus consecuencias?</p><p>Termina con dos versiones: una corrección mínima que conserve la estructura y una reescritura que mejore la decisión. No conviertas la auditoría en una competencia por detectar errores pequeños; prioriza lo que cambiaría una decisión razonable. Guarda el mensaje inicial y la justificación de los cambios para comprobar si mejoró la claridad, no sólo si suena más elegante.</p>"},{"tipo":"destacado","texto":"Caso ficticio: «Desde $80 al día y resultados garantizados». La letra pequeña exige doce meses y la garantía sólo cubre acceso a la plataforma."},{"tipo":"practica","rotulo":"Decide y contrasta","preguntas":[{"p":"¿Qué corregirías primero?","ops":["Explicar el compromiso total y el alcance exacto de la garantía.","Cambiar el color del anuncio para transmitir confianza.","Agregar un testimonio sin aclarar las condiciones."],"correcta":0,"explica":"La omisión afecta la decisión económica y la expectativa de resultado. La estética y el testimonio no corrigen esa información.","pista":"Revisa la restricción del caso y el efecto de tu respuesta sobre la decisión de la otra persona."}]},{"tipo":"completar","rotulo":"Recupera la idea clave","items":[{"frase":"Una auditoría distingue hechos, promesas, interpretaciones y ___.","resp":["omisiones"],"explica":"Relaciona este concepto con la decisión que acabas de analizar."}]},{"tipo":"reflexion","rotulo":"Práctica aplicada · 20 minutos orientativos","pregunta":"Aplica una matriz con cinco columnas a un anuncio inventado: afirmación, tipo, evidencia, condición omitida y corrección. Prioriza dos cambios.","ayuda":"Primera versión, contraste con el modelo y revisión propia."},{"tipo":"texto","texto":"<details><summary>Consultar modelo y retroalimentación</summary><p>Modelo: para «garantizado», pedir el objeto de la garantía; para «$80 al día», mostrar precio total y permanencia. La versión revisada no debe convertir una garantía de acceso en una promesa de aprendizaje individual.</p><p>Compara tu respuesta: identifica una condición explícita, una afirmación que necesita respaldo y una mejora concreta. El modelo es una posibilidad, no la única respuesta válida.</p></details>"},{"tipo":"texto","texto":"<h3>Reto del módulo · 90 minutos orientativos</h3><p>Audita tres mensajes ficticios: una invitación comunitaria, una oferta de servicio y una solicitud a un equipo. Señala qué se pide, qué evidencia existe, qué información falta y cómo se puede rechazar. Reescribe uno y explica tus cambios.</p><p><strong>Entregable:</strong> Matriz de tres mensajes y dos versiones comentadas de una propuesta.</p><p>Diagnóstico 15 min; primera versión 30; contraste 20; revisión 15; reflexión 10.</p>"},{"tipo":"reflexion","rotulo":"Bitácora del reto","pregunta":"Registra tu primera versión, una condición que faltaba y tu revisión justificada."},{"tipo":"texto","texto":"<h3>Autoevaluación del reto</h3><p>Revisa decisión clara, evidencia pertinente, condiciones explícitas y respeto al rechazo. En cada criterio: 0 ausente; 1 genérico; 2 concreto y justificado. Corrige los criterios con 0. Usa los modelos de las cuatro lecciones para contrastar tus decisiones.</p>"}],"minutosEstimados":45}],"quiz":{"titulo":"Evaluación de aplicación","preguntas":[{"p":"Una membresía se anuncia por mes pero exige permanencia anual. ¿Qué dato debe destacarse antes de pagar?","ops":["El compromiso total y las condiciones de salida.","Únicamente la cuota mensual.","La cantidad de seguidores de la marca."],"correcta":0,"explica":"La permanencia puede cambiar la decisión; no debe ocultarse detrás del precio mensual."},{"p":"Una persona entiende tu propuesta y la rechaza. ¿Qué demuestra ese resultado?","ops":["Que no has persuadido con suficiente intensidad.","Que debes repetir la oferta hasta obtener un sí.","Que puede existir una decisión informada sin aceptación."],"correcta":2,"explica":"La autonomía incluye rechazar una propuesta comprendida."},{"p":"Recibes una comisión por recomendar un servicio. ¿Qué acción es adecuada?","ops":["Declarar la comisión y dejar de explicar las condiciones.","Declarar el incentivo y justificar para quién resulta pertinente.","Omitir la comisión si el servicio es bueno."],"correcta":1,"explica":"La transparencia sobre el incentivo no sustituye la evidencia de conveniencia."},{"p":"Un contador de oferta se reinicia cada mañana aunque anuncia último día. ¿Qué revisarías?","ops":["La veracidad de la restricción temporal.","Sólo la tipografía del contador.","Si genera suficientes ventas."],"correcta":0,"explica":"El problema es presentar como excepcional una restricción que no existe."},{"p":"Quedan dos espacios por capacidad del salón. ¿Qué puedes afirmar?","ops":["Ésta es la última oportunidad de aprender en la vida.","Quien dude no está comprometido con su desarrollo.","Quedan dos espacios en esta edición."],"correcta":2,"explica":"La capacidad permite comunicar escasez real, no inferir compromiso ni consecuencias vitales."},{"p":"Una garantía sólo cubre acceso al material. ¿Qué frase es precisa?","ops":["Se garantiza conseguir empleo.","Se garantiza acceso en las condiciones descritas.","Se garantiza que todos dominarán la habilidad."],"correcta":1,"explica":"Una garantía de acceso no demuestra un resultado de aprendizaje o laboral."},{"p":"Un mensaje tiene frases ciertas pero omite un cargo obligatorio. ¿Cómo lo evalúas?","ops":["La impresión general puede ser engañosa por omisión.","Es transparente porque ninguna frase es falsa.","El cargo puede mostrarse después de la aceptación."],"correcta":0,"explica":"La decisión requiere considerar también condiciones relevantes que faltan."},{"p":"Quieres convencer a un equipo de usar una herramienta. ¿Qué presentarías?","ops":["Sólo los beneficios para evitar dudas.","Una amenaza de exclusión para acelerar el cambio.","Beneficios esperados, esfuerzo, límites y opción de revisión."],"correcta":2,"explica":"La propuesta debe permitir comparar beneficios y costos reales."},{"p":"Tu objetivo beneficia a la comunidad. ¿Qué implica para los medios?","ops":["No es necesario permitir el desacuerdo.","También deben revisarse su transparencia y consecuencias.","Cualquier exageración queda justificada."],"correcta":1,"explica":"La intención favorable no legitima cualquier táctica."},{"p":"¿Cuál es una llamada a la acción suficientemente clara?","ops":["Solicita una demostración gratuita; no inicia una suscripción.","Da el paso que cambiará tu vida.","No te quedes atrás."],"correcta":0,"explica":"La primera explica la acción concreta y una consecuencia relevante."}]}},{"id":"pe-m02","titulo":"Comprender a la audiencia","resumen":"Prepara una entrevista de descubrimiento de ocho preguntas. Simula dos respuestas distintas y adapta una propuesta sin inventar necesidades. Usa un caso ficticio si no quieres entrevistar a alguien.","lecciones":[{"id":"pe-m02-l1","titulo":"Objetivos y restricciones","objetivo":"Aplicar objetivos y restricciones mediante un caso, una decisión comentada y una producción propia.","bloques":[{"tipo":"imagen","url":"recursos/diplomado-persuasion-etica/visuales/pe-m02.svg","pie":"Mapa del módulo: Objetivos y restricciones; Preguntas que abren información; Escuchar, parafrasear y verificar; Mapa de interlocutores"},{"tipo":"texto","texto":"<p>Una audiencia no es una etiqueta. «Jóvenes», «directivos» o «clientes difíciles» agrupan personas con situaciones distintas. Empieza por la tarea que intentan resolver y las condiciones que restringen su elección: tiempo, dinero, responsabilidad, accesibilidad o acuerdos con terceros.</p><p>Distingue objetivo declarado, resultado esperado y restricción. «Quiero un curso breve» es una preferencia; «necesito presentar un informe el viernes» explica una tarea; «sólo tengo treinta minutos al día» delimita la solución. Puedes preguntar qué significa breve antes de proponer un producto.</p><p>Registra tus hipótesis como hipótesis. Una persona que pregunta por precio puede estar comparando proveedores, buscando autorización o cuidando un presupuesto, no necesariamente rechazando el valor. Pregunta qué información le ayudaría a decidir y qué alternativa está considerando. Diseñar para restricciones reales suele ser más útil que buscar una frase supuestamente irresistible.</p>"},{"tipo":"tarjetas","rotulo":"Guía activa del módulo · anticipa, compara y repasa","voz":false,"tarjetas":[{"frente":"¿Cómo aplicarías «Objetivos y restricciones»? Piensa en una acción concreta antes de voltear.","reverso":"Modelo: dos personas quieren mejorar presentaciones; una necesita una intervención de tres minutos mañana y otra tiene un mes para un informe técnico. Cambian práctica, alcance y recursos, aunque el tema general sea el mismo.","ej":"Al terminar el módulo, vuelve a esta tarjeta y formula tu propio ejemplo."},{"frente":"¿Cómo aplicarías «Preguntas que abren información»? Piensa en una acción concreta antes de voltear.","reverso":"Modelo: sustituye «¿verdad que necesitas más funciones?» por «¿qué tarea no puedes completar hoy?». Si ninguna tarea falta, la respuesta puede llevarte a no recomendar una ampliación.","ej":"Al terminar el módulo, vuelve a esta tarjeta y formula tu propio ejemplo."},{"frente":"¿Cómo aplicarías «Escuchar, parafrasear y verificar»? Piensa en una acción concreta antes de voltear.","reverso":"Modelo: «Necesitas flexibilidad de horario; ¿te serviría un formato a tu ritmo?» es una comprobación, no una promesa. Si responde que no, pregunta qué condición adicional falta en lugar de insistir con la misma oferta.","ej":"Al terminar el módulo, vuelve a esta tarjeta y formula tu propio ejemplo."},{"frente":"¿Cómo aplicarías «Mapa de interlocutores»? Piensa en una acción concreta antes de voltear.","reverso":"Modelo: para cambiar el horario de una biblioteca, incluye usuarios, personal, administración y quienes abren el edificio. Contrasta necesidades con disponibilidad antes de pedir apoyo; no atribuyas mala voluntad a quien señala una limitación.","ej":"Al terminar el módulo, vuelve a esta tarjeta y formula tu propio ejemplo."}]},{"tipo":"destacado","texto":"Caso ficticio: Miriam dice que necesita una capacitación corta porque presentará un proyecto la próxima semana."},{"tipo":"practica","rotulo":"Decide y contrasta","preguntas":[{"p":"¿Qué conviene preguntar primero?","ops":["Qué promoción la haría comprar hoy.","Por qué no se organizó con más anticipación.","Qué debe poder hacer en la presentación y cuánto tiempo tiene para prepararse."],"correcta":2,"explica":"La pregunta conecta resultado y restricción. Descontar antes de comprender puede ofrecer algo barato que no resuelve la necesidad.","pista":"Revisa la restricción del caso y el efecto de tu respuesta sobre la decisión de la otra persona."}]},{"tipo":"completar","rotulo":"Recupera la idea clave","items":[{"frase":"El tiempo disponible es una ___, no un defecto de la persona.","resp":["restricción"],"explica":"Relaciona este concepto con la decisión que acabas de analizar."}]},{"tipo":"reflexion","rotulo":"Práctica aplicada · 20 minutos orientativos","pregunta":"Crea dos perfiles de audiencia con el mismo interés y restricciones diferentes. Diseña una propuesta distinta para cada perfil y explica qué dato la justifica.","ayuda":"Primera versión, contraste con el modelo y revisión propia."},{"tipo":"texto","texto":"<details><summary>Consultar modelo y retroalimentación</summary><p>Modelo: dos personas quieren mejorar presentaciones; una necesita una intervención de tres minutos mañana y otra tiene un mes para un informe técnico. Cambian práctica, alcance y recursos, aunque el tema general sea el mismo.</p><p>Compara tu respuesta: identifica una condición explícita, una afirmación que necesita respaldo y una mejora concreta. El modelo es una posibilidad, no la única respuesta válida.</p></details>"}],"minutosEstimados":45},{"id":"pe-m02-l2","titulo":"Preguntas que abren información","objetivo":"Aplicar preguntas que abren información mediante un caso, una decisión comentada y una producción propia.","bloques":[{"tipo":"texto","texto":"<p>Una pregunta abierta permite desarrollar una respuesta; una cerrada comprueba un dato específico. Ambas son útiles. «¿Qué dificultades encontraste?» explora, mientras «¿el plazo vence el viernes?» confirma. El problema aparece cuando la pregunta incluye la respuesta deseada: «¿no crees que nuestra solución es claramente superior?».</p><p>Usa una secuencia de apertura, seguimiento y comprobación. Pregunta por la situación, retoma una palabra relevante y confirma lo entendido. Haz una pregunta cada vez: una lista de cinco preguntas suele producir respuestas sólo a la última.</p><p>Evita convertir la conversación en interrogatorio. Explica para qué necesitas un dato y acepta que la persona no lo comparta. No recolectes información personal que no cambia la propuesta. Una buena pregunta no es la más ingeniosa, sino la que reduce una incertidumbre concreta y permite que la respuesta modifique tu recomendación.</p>"},{"tipo":"destacado","texto":"Caso ficticio: Óscar dice que el sistema anterior «era complicado»."},{"tipo":"practica","rotulo":"Decide y contrasta","preguntas":[{"p":"¿Cuál es el seguimiento más útil?","ops":["¿Era malo, lento, caro y difícil de usar?","¿Qué tarea concreta te resultaba complicada y qué ocurría al intentarla?","¿Entonces admites que necesitas nuestro sistema?"],"correcta":1,"explica":"La primera pregunta pide un ejemplo sin imponer una interpretación. La segunda busca adhesión; la tercera mezcla dimensiones y dificulta saber qué se está respondiendo.","pista":"Revisa la restricción del caso y el efecto de tu respuesta sobre la decisión de la otra persona."}]},{"tipo":"completar","rotulo":"Recupera la idea clave","items":[{"frase":"Después de explorar, una pregunta cerrada puede ___ un dato.","resp":["confirmar"],"explica":"Relaciona este concepto con la decisión que acabas de analizar."}]},{"tipo":"reflexion","rotulo":"Práctica aplicada · 20 minutos orientativos","pregunta":"Transforma cinco preguntas dirigidas en preguntas neutrales. Indica qué incertidumbre resuelve cada una y cuál sería tu siguiente pregunta.","ayuda":"Primera versión, contraste con el modelo y revisión propia."},{"tipo":"texto","texto":"<details><summary>Consultar modelo y retroalimentación</summary><p>Modelo: sustituye «¿verdad que necesitas más funciones?» por «¿qué tarea no puedes completar hoy?». Si ninguna tarea falta, la respuesta puede llevarte a no recomendar una ampliación.</p><p>Compara tu respuesta: identifica una condición explícita, una afirmación que necesita respaldo y una mejora concreta. El modelo es una posibilidad, no la única respuesta válida.</p></details>"},{"tipo":"relacionar","rotulo":"Relaciona el concepto con su aplicación","voz":false,"pares":[["Observación","La reunión terminó veinte minutos después"],["Interpretación","Creo que el equipo no está interesado"],["Pregunta abierta","¿Qué dificulta preparar la reunión?"],["Verificación","¿Entendí bien que necesitas recibir la agenda antes?"]]},{"tipo":"texto","texto":"<p><strong>Contrasta tu razonamiento:</strong> después de relacionar, explica por qué cada ejemplo corresponde a ese concepto y escribe un contraejemplo. No basta memorizar la pareja: identifica la conducta observable que la distingue.</p>"}],"minutosEstimados":45},{"id":"pe-m02-l3","titulo":"Escuchar, parafrasear y verificar","objetivo":"Aplicar escuchar, parafrasear y verificar mediante un caso, una decisión comentada y una producción propia.","bloques":[{"tipo":"texto","texto":"<p>Escuchar no consiste en permanecer callado mientras preparas tu réplica. Busca comprender el contenido, el significado que la persona le atribuye y la petición concreta. Puedes tomar notas breves para no depender de memoria selectiva.</p><p>Parafrasear significa expresar con tus palabras lo que entendiste y ofrecer la oportunidad de corregirlo. «Entiendo que necesitas reducir pasos, aunque no necesariamente cambiar de proveedor; ¿es así?» hace visible tu interpretación. No agregues motivos que la persona no ha expresado: «en realidad tienes miedo al cambio» sería una conjetura presentada como hecho.</p><p>Validar una preocupación no significa aceptar todas las afirmaciones. Puedes reconocer que un plazo preocupa y, al mismo tiempo, aclarar que no puedes garantizarlo. Al terminar, confirma acuerdos, desacuerdos y datos pendientes por separado. Si sólo repites las palabras literalmente, la conversación puede parecer mecánica; si interpretas demasiado, corres el riesgo de reemplazar la voz ajena por la tuya.</p>"},{"tipo":"destacado","texto":"Caso ficticio: «No estoy diciendo que el curso sea malo; no puedo conectarme a esa hora»."},{"tipo":"practica","rotulo":"Decide y contrasta","preguntas":[{"p":"¿Qué paráfrasis respeta el mensaje?","ops":["El obstáculo es el horario, no has cuestionado el contenido; ¿lo entendí bien?","Te falta motivación para priorizarlo.","Ya estás de acuerdo en comprar si insisto un poco."],"correcta":0,"explica":"La paráfrasis separa la restricción de una evaluación del curso y permite corrección. No convierte una explicación en intención de compra.","pista":"Revisa la restricción del caso y el efecto de tu respuesta sobre la decisión de la otra persona."}]},{"tipo":"completar","rotulo":"Recupera la idea clave","items":[{"frase":"Una paráfrasis termina ofreciendo la oportunidad de ___.","resp":["corregir"],"explica":"Relaciona este concepto con la decisión que acabas de analizar."}]},{"tipo":"reflexion","rotulo":"Práctica aplicada · 20 minutos orientativos","pregunta":"Escribe tres respuestas a una objeción: una que la distorsione, una que la repita literalmente y una que la parafrasee con verificación. Explica la diferencia.","ayuda":"Primera versión, contraste con el modelo y revisión propia."},{"tipo":"texto","texto":"<details><summary>Consultar modelo y retroalimentación</summary><p>Modelo: «Necesitas flexibilidad de horario; ¿te serviría un formato a tu ritmo?» es una comprobación, no una promesa. Si responde que no, pregunta qué condición adicional falta en lugar de insistir con la misma oferta.</p><p>Compara tu respuesta: identifica una condición explícita, una afirmación que necesita respaldo y una mejora concreta. El modelo es una posibilidad, no la única respuesta válida.</p></details>"}],"minutosEstimados":45},{"id":"pe-m02-l4","titulo":"Mapa de interlocutores","objetivo":"Aplicar mapa de interlocutores mediante un caso, una decisión comentada y una producción propia.","bloques":[{"tipo":"texto","texto":"<p>La persona que conversa contigo no siempre decide sola. Puede usar el producto, autorizar presupuesto, comprobar requisitos o recibir sus consecuencias. Identificar esas funciones ayuda a preparar información pertinente sin buscar saltarse acuerdos internos.</p><p>Construye un mapa con cuatro columnas: persona o función, criterio de decisión, información necesaria y participación acordada. No necesitas nombres privados; puedes trabajar con roles. Un usuario quiere facilidad de uso y quien administra presupuesto necesita costo total. Sus intereses pueden coexistir.</p><p>Evita dividir a todos en aliados y enemigos. Un participante que cuestiona seguridad puede estar cuidando una condición legítima del proyecto. Pregunta cómo se tomará la decisión y quién debe revisar qué. No uses información confidencial de un interlocutor para presionar a otro. El mapa es una herramienta de coordinación, no una lista de vulnerabilidades.</p>"},{"tipo":"destacado","texto":"Caso ficticio: una escuela evalúa software. Docentes lo usarán, dirección autoriza y administración revisa contratos."},{"tipo":"practica","rotulo":"Decide y contrasta","preguntas":[{"p":"¿Qué propuesta organiza mejor la decisión?","ops":["Convencer a un docente para que oculte el costo hasta obtener aprobación.","Enviar exactamente el mismo argumento a todos sin conocer sus criterios.","Preparar demostración de uso, costo total y condiciones para las funciones correspondientes."],"correcta":2,"explica":"Adaptar información no significa alterar hechos: las funciones reciben detalles pertinentes de una misma propuesta. Ocultar costos rompe transparencia.","pista":"Revisa la restricción del caso y el efecto de tu respuesta sobre la decisión de la otra persona."}]},{"tipo":"completar","rotulo":"Recupera la idea clave","items":[{"frase":"El mapa debe distinguir quién usa, quién autoriza y quién ___ condiciones.","resp":["revisa"],"explica":"Relaciona este concepto con la decisión que acabas de analizar."}]},{"tipo":"reflexion","rotulo":"Práctica aplicada · 20 minutos orientativos","pregunta":"Dibuja el mapa de una decisión comunitaria con cuatro roles. Anota un posible desacuerdo legítimo y una forma de coordinarlo.","ayuda":"Primera versión, contraste con el modelo y revisión propia."},{"tipo":"texto","texto":"<details><summary>Consultar modelo y retroalimentación</summary><p>Modelo: para cambiar el horario de una biblioteca, incluye usuarios, personal, administración y quienes abren el edificio. Contrasta necesidades con disponibilidad antes de pedir apoyo; no atribuyas mala voluntad a quien señala una limitación.</p><p>Compara tu respuesta: identifica una condición explícita, una afirmación que necesita respaldo y una mejora concreta. El modelo es una posibilidad, no la única respuesta válida.</p></details>"},{"tipo":"texto","texto":"<h3>Reto del módulo · 90 minutos orientativos</h3><p>Prepara una entrevista de descubrimiento de ocho preguntas. Simula dos respuestas distintas y adapta una propuesta sin inventar necesidades. Usa un caso ficticio si no quieres entrevistar a alguien.</p><p><strong>Entregable:</strong> Guion, notas separadas en hechos e hipótesis y propuesta adaptada.</p><p>Diagnóstico 15 min; primera versión 30; contraste 20; revisión 15; reflexión 10.</p>"},{"tipo":"reflexion","rotulo":"Bitácora del reto","pregunta":"Registra tu primera versión, una condición que faltaba y tu revisión justificada."},{"tipo":"texto","texto":"<h3>Autoevaluación del reto</h3><p>Revisa decisión clara, evidencia pertinente, condiciones explícitas y respeto al rechazo. En cada criterio: 0 ausente; 1 genérico; 2 concreto y justificado. Corrige los criterios con 0. Usa los modelos de las cuatro lecciones para contrastar tus decisiones.</p>"}],"minutosEstimados":45}],"quiz":{"titulo":"Evaluación de aplicación","preguntas":[{"p":"Un cliente dice que quiere ahorrar tiempo. ¿Qué preguntarías primero?","ops":["Qué producto de tu catálogo prefiere comprar.","Por qué no trabaja más rápido.","En qué tarea y cuánto tiempo emplea hoy."],"correcta":2,"explica":"Una necesidad general requiere concretar tarea, situación y medida."},{"p":"¿Qué nota separa mejor un hecho de una hipótesis?","ops":["Seguro no puede aprender de manera autónoma.","Dijo que dispone de una hora; quizá necesite sesiones breves.","Es una persona poco comprometida."],"correcta":1,"explica":"La nota distingue información declarada de interpretación pendiente de comprobar."},{"p":"La persona corrige tu paráfrasis. ¿Qué haces?","ops":["Ajustas tu comprensión y confirmas de nuevo.","Defiendes que tú entendiste lo importante.","Cambias de tema para no perder autoridad."],"correcta":0,"explica":"La paráfrasis comprueba comprensión y admite correcciones."},{"p":"Quien usará el sistema no autoriza el gasto. ¿Qué falta identificar?","ops":["Únicamente el cargo más alto.","El número de seguidores del usuario.","Quién decide, quién usa y quién resulta afectado."],"correcta":2,"explica":"Los papeles pueden distribuirse entre varias personas."},{"p":"¿Cuál pregunta permite explorar sin dirigir demasiado?","ops":["¿No sería irresponsable seguir igual?","¿Qué dificulta hoy la coordinación del equipo?","¿Verdad que necesitan nuestra solución?"],"correcta":1,"explica":"Una pregunta abierta no incorpora la respuesta que deseas obtener."},{"p":"La audiencia tiene necesidades contradictorias. ¿Qué conviene hacer?","ops":["Describir los criterios y buscar acuerdos posibles.","Inventar una necesidad común para simplificar.","Elegir por todos sin explicar la decisión."],"correcta":0,"explica":"Reconocer diferencias evita construir propuestas sobre un consenso inexistente."},{"p":"¿Qué información debería limitar una propuesta de formación?","ops":["Suposiciones basadas sólo en la edad.","La insistencia del vendedor.","Disponibilidad real, conocimientos previos y objetivo."],"correcta":2,"explica":"Las restricciones concretas importan más que estereotipos demográficos."},{"p":"Una entrevista produjo una frase ambigua. ¿Cuál es el siguiente paso?","ops":["Convertirla de inmediato en una promesa comercial.","Pedir un ejemplo reciente de lo que significa.","Interpretarla del modo más favorable a tu oferta."],"correcta":1,"explica":"Un ejemplo permite precisar sin inventar el sentido."},{"p":"¿Para qué sirve una síntesis al terminar una entrevista?","ops":["Confirmar prioridades y aspectos aún desconocidos.","Demostrar que ya conoces todas las respuestas.","Obtener aceptación antes de explicar el precio."],"correcta":0,"explica":"La síntesis ayuda a corregir errores y conservar incertidumbres."},{"p":"No puedes entrevistar a usuarios esta semana. ¿Cómo trabajas responsablemente?","ops":["Los presentas como resultados de investigación.","Omites las restricciones del proyecto.","Etiquetas tus supuestos y preparas cómo validarlos."],"correcta":2,"explica":"Una hipótesis útil sigue siendo una hipótesis hasta contrastarla."}]}},{"id":"pe-m03","titulo":"Opiniones, atención y decisiones","resumen":"Analiza una objeción desde dos explicaciones alternativas. Propón qué pregunta o dato permitiría distinguirlas. Redacta un mensaje que pueda cambiar si aparece evidencia contraria.","lecciones":[{"id":"pe-m03-l1","titulo":"Actitudes, creencias y valores","objetivo":"Aplicar actitudes, creencias y valores mediante un caso, una decisión comentada y una producción propia.","bloques":[{"tipo":"imagen","url":"recursos/diplomado-persuasion-etica/visuales/pe-m03.svg","pie":"Mapa del módulo: Actitudes, creencias y valores; Atención y procesamiento; Sesgos y explicaciones alternativas; Resistencia y cambio de opinión"},{"tipo":"texto","texto":"<p>Una creencia describe lo que alguien considera verdadero; una actitud expresa una evaluación; un valor señala algo importante para esa persona. «Las reuniones virtuales fallan» es una creencia general, «no me gustan» una actitud y «quiero cuidar el tiempo del equipo» puede expresar un valor.</p><p>Estas categorías ayudan a formular preguntas, pero no son compartimentos perfectos ni diagnósticos. Una objeción puede combinar las tres. Si discutes datos cuando la preocupación es una prioridad, puedes responder correctamente a una pregunta que nadie hizo.</p><p>Pide ejemplos y condiciones: ¿qué ocurrió?, ¿qué tendría que cambiar?, ¿qué no quieres sacrificar? No conviertas el valor declarado en una palanca de culpa: «si valoras a tu familia debes comprar» no demuestra que el producto sea adecuado. Busca compatibilidad entre propuesta y prioridades, y reconoce cuando no la hay.</p>"},{"tipo":"tarjetas","rotulo":"Guía activa del módulo · anticipa, compara y repasa","voz":false,"tarjetas":[{"frente":"¿Cómo aplicarías «Actitudes, creencias y valores»? Piensa en una acción concreta antes de voltear.","reverso":"Modelo: «Esto no funciona» puede significar fallas observadas o frustración. «¿Qué intentaste y qué resultado obtuviste?» permite precisar la creencia sin negar la experiencia.","ej":"Al terminar el módulo, vuelve a esta tarjeta y formula tu propio ejemplo."},{"frente":"¿Cómo aplicarías «Atención y procesamiento»? Piensa en una acción concreta antes de voltear.","reverso":"Modelo: la apertura de una prueba incluye duración, responsables, costo y cómo terminarla. El anexo puede explicar características técnicas. Una penalización por cancelación, si existe, no debe quedar fuera de la decisión principal.","ej":"Al terminar el módulo, vuelve a esta tarjeta y formula tu propio ejemplo."},{"frente":"¿Cómo aplicarías «Sesgos y explicaciones alternativas»? Piensa en una acción concreta antes de voltear.","reverso":"Modelo: antes de recomendar una herramienta, compara tareas completadas, abandonos y problemas reportados. No basta con añadir una reseña negativa simbólica si ignoras un patrón consistente de fallas.","ej":"Al terminar el módulo, vuelve a esta tarjeta y formula tu propio ejemplo."},{"frente":"¿Cómo aplicarías «Resistencia y cambio de opinión»? Piensa en una acción concreta antes de voltear.","reverso":"Modelo: probar una agenda compartida durante dos semanas con un solo equipo; mantener respaldo del sistema anterior; suspender si impide registrar tareas. Un resultado negativo también es información útil.","ej":"Al terminar el módulo, vuelve a esta tarjeta y formula tu propio ejemplo."}]},{"tipo":"destacado","texto":"Caso ficticio: «No quiero reuniones extra; me importa terminar a tiempo para cuidar a mi familia»."},{"tipo":"practica","rotulo":"Decide y contrasta","preguntas":[{"p":"¿Qué respuesta comprende la prioridad?","ops":["Mostrar una estadística de popularidad sin discutir horarios.","Explorar una alternativa que no extienda la jornada.","Decir que quien valora a su familia debería comprar cualquier solución de productividad."],"correcta":1,"explica":"La prioridad expresada afecta la solución. Utilizarla para provocar culpa no prueba conveniencia ni resuelve la restricción.","pista":"Revisa la restricción del caso y el efecto de tu respuesta sobre la decisión de la otra persona."}]},{"tipo":"completar","rotulo":"Recupera la idea clave","items":[{"frase":"Lo que una persona considera importante se relaciona con sus ___.","resp":["valores"],"explica":"Relaciona este concepto con la decisión que acabas de analizar."}]},{"tipo":"reflexion","rotulo":"Práctica aplicada · 20 minutos orientativos","pregunta":"Clasifica seis frases propias entre creencias, actitudes y valores. Elige una ambigua y escribe una pregunta que ayude a entenderla.","ayuda":"Primera versión, contraste con el modelo y revisión propia."},{"tipo":"texto","texto":"<details><summary>Consultar modelo y retroalimentación</summary><p>Modelo: «Esto no funciona» puede significar fallas observadas o frustración. «¿Qué intentaste y qué resultado obtuviste?» permite precisar la creencia sin negar la experiencia.</p><p>Compara tu respuesta: identifica una condición explícita, una afirmación que necesita respaldo y una mejora concreta. El modelo es una posibilidad, no la única respuesta válida.</p></details>"}],"minutosEstimados":45},{"id":"pe-m03-l2","titulo":"Atención y procesamiento","objetivo":"Aplicar atención y procesamiento mediante un caso, una decisión comentada y una producción propia.","bloques":[{"tipo":"texto","texto":"<p>La calidad de un argumento importa, pero para examinarlo hacen falta atención, comprensión y tiempo. Las personas no revisan toda la información con la misma profundidad en todos los momentos. Una explicación extensa puede fallar por carga excesiva; una explicación breve puede fallar por omitir lo esencial.</p><p>Diseña capas: primero la decisión y las condiciones principales; después razones; finalmente evidencia y detalles consultables. Facilitar la lectura no significa aprovechar distracciones para esconder términos. Una persona debe poder detenerse y revisar.</p><p>No conviertas modelos psicológicos en recetas universales del cerebro. El conocimiento previo, interés, contexto y consecuencias de la decisión influyen en cómo se examina un mensaje. Pide que el interlocutor explique qué entendió en lugar de confundir asentir con comprender. Si detectas una diferencia, reformula sin culparlo por no haber prestado atención.</p>"},{"tipo":"destacado","texto":"Caso ficticio: presentas doce diapositivas técnicas a alguien que sólo necesita decidir si autoriza una prueba de una semana."},{"tipo":"practica","rotulo":"Decide y contrasta","preguntas":[{"p":"¿Qué reorganización ayuda?","ops":["Abrir con objetivo, costo y alcance de la prueba, dejando detalles técnicos disponibles.","Ocultar las condiciones en una diapositiva que pase rápido.","Añadir más tecnicismos para que parezca riguroso."],"correcta":0,"explica":"La estructura por capas facilita examen y conserva acceso a los detalles. La rapidez o complejidad no sustituyen comprensión.","pista":"Revisa la restricción del caso y el efecto de tu respuesta sobre la decisión de la otra persona."}]},{"tipo":"completar","rotulo":"Recupera la idea clave","items":[{"frase":"Organizar información por ___ permite empezar por lo esencial y ampliar después.","resp":["capas"],"explica":"Relaciona este concepto con la decisión que acabas de analizar."}]},{"tipo":"reflexion","rotulo":"Práctica aplicada · 20 minutos orientativos","pregunta":"Reduce una explicación de 250 palabras a una apertura de 60 y un anexo de detalles. Marca qué información nunca debe quedar oculta.","ayuda":"Primera versión, contraste con el modelo y revisión propia."},{"tipo":"texto","texto":"<details><summary>Consultar modelo y retroalimentación</summary><p>Modelo: la apertura de una prueba incluye duración, responsables, costo y cómo terminarla. El anexo puede explicar características técnicas. Una penalización por cancelación, si existe, no debe quedar fuera de la decisión principal.</p><p>Compara tu respuesta: identifica una condición explícita, una afirmación que necesita respaldo y una mejora concreta. El modelo es una posibilidad, no la única respuesta válida.</p></details>"},{"tipo":"relacionar","rotulo":"Relaciona el concepto con su aplicación","voz":false,"pares":[["Creencia","Considerar que una herramienta ahorra tiempo"],["Valor","Dar prioridad a la equidad entre turnos"],["Restricción","Disponer de sólo quince minutos"],["Hipótesis alternativa","La objeción puede deberse al horario y no al desinterés"]]},{"tipo":"texto","texto":"<p><strong>Contrasta tu razonamiento:</strong> después de relacionar, explica por qué cada ejemplo corresponde a ese concepto y escribe un contraejemplo. No basta memorizar la pareja: identifica la conducta observable que la distingue.</p>"}],"minutosEstimados":45},{"id":"pe-m03-l3","titulo":"Sesgos y explicaciones alternativas","objetivo":"Aplicar sesgos y explicaciones alternativas mediante un caso, una decisión comentada y una producción propia.","bloques":[{"tipo":"texto","texto":"<p>Un sesgo es una tendencia que puede afectar el juicio; no una etiqueta que demuestre que otra persona está equivocada. También afecta a quien persuade. Si sólo buscas clientes satisfechos, puedes construir una conclusión con información seleccionada.</p><p>Revisa selección de evidencia, comparación inicial y disponibilidad de ejemplos llamativos. Antes de aceptar tu primera explicación, escribe otra plausible. Un silencio puede deberse a desacuerdo, cansancio, problemas de conexión o necesidad de consultar a alguien. No lo interpretes como una señal universal de rechazo.</p><p>Para reducir errores, define qué dato cambiaría tu opinión, busca una fuente discrepante y revisa el punto de comparación. No puedes eliminar toda influencia del contexto; sí hacer más visible tu razonamiento. Al comunicar un posible sesgo, describe el procedimiento que propones mejorar, no la supuesta inferioridad mental de quien discrepa.</p>"},{"tipo":"destacado","texto":"Caso ficticio: nueve clientes respondieron una encuesta; sólo se invitó a quienes habían recomendado el producto."},{"tipo":"practica","rotulo":"Decide y contrasta","preguntas":[{"p":"¿Qué limita la conclusión?","ops":["Nueve respuestas demuestran que todos los clientes están satisfechos.","La encuesta es falsa necesariamente, sin revisar los datos.","La selección de participantes puede dejar fuera experiencias distintas."],"correcta":2,"explica":"La selección limita la generalización. Eso no demuestra que las respuestas sean inventadas; exige describir a quiénes representan.","pista":"Revisa la restricción del caso y el efecto de tu respuesta sobre la decisión de la otra persona."}]},{"tipo":"completar","rotulo":"Recupera la idea clave","items":[{"frase":"Buscar sólo datos favorables puede reforzar el sesgo de ___.","resp":["confirmación"],"explica":"Relaciona este concepto con la decisión que acabas de analizar."}]},{"tipo":"reflexion","rotulo":"Práctica aplicada · 20 minutos orientativos","pregunta":"Escribe una conclusión que defiendes, dos datos que la apoyarían y dos que te harían revisarla. Diseña cómo buscarías los cuatro.","ayuda":"Primera versión, contraste con el modelo y revisión propia."},{"tipo":"texto","texto":"<details><summary>Consultar modelo y retroalimentación</summary><p>Modelo: antes de recomendar una herramienta, compara tareas completadas, abandonos y problemas reportados. No basta con añadir una reseña negativa simbólica si ignoras un patrón consistente de fallas.</p><p>Compara tu respuesta: identifica una condición explícita, una afirmación que necesita respaldo y una mejora concreta. El modelo es una posibilidad, no la única respuesta válida.</p></details>"}],"minutosEstimados":45},{"id":"pe-m03-l4","titulo":"Resistencia y cambio de opinión","objetivo":"Aplicar resistencia y cambio de opinión mediante un caso, una decisión comentada y una producción propia.","bloques":[{"tipo":"texto","texto":"<p>La resistencia no es siempre falta de información. Puede reflejar costos de cambio, pérdida de control, experiencias previas o desacuerdo razonado. Repetir el mismo argumento con más volumen no identifica cuál de esos factores está presente.</p><p>Explora qué preocupa y qué parte de la propuesta se rechaza. Ofrece opciones reales, incluyendo no actuar cuando sea viable. Una prueba pequeña puede disminuir incertidumbre, siempre que sus costos, límites y salida estén claros. No llames prueba gratuita a un compromiso que luego activa cargos sin explicación.</p><p>Cambiar de opinión lleva condiciones diferentes según la situación. No prometas lograrlo en una cantidad fija de pasos. Define una conversación satisfactoria como aquella que aclara razones y alternativas, incluso si termina sin acuerdo. Cuando recibes una negativa clara, respétala; un seguimiento requiere una razón y, cuando corresponde, autorización.</p>"},{"tipo":"destacado","texto":"Caso ficticio: un equipo no quiere migrar de software por una experiencia anterior con pérdida de archivos."},{"tipo":"practica","rotulo":"Decide y contrasta","preguntas":[{"p":"¿Qué respuesta aborda la resistencia?","ops":["Exigir el cambio completo para demostrar compromiso.","Preguntar por el incidente y proponer evaluar respaldo y recuperación antes de decidir.","Afirmar que el miedo al cambio siempre es irracional."],"correcta":1,"explica":"La preocupación apunta a un riesgo concreto. Evaluarlo permite decidir; descalificarlo o exigir compromiso no aporta evidencia.","pista":"Revisa la restricción del caso y el efecto de tu respuesta sobre la decisión de la otra persona."}]},{"tipo":"completar","rotulo":"Recupera la idea clave","items":[{"frase":"Una prueba responsable aclara sus límites, costos y forma de ___.","resp":["salida"],"explica":"Relaciona este concepto con la decisión que acabas de analizar."}]},{"tipo":"reflexion","rotulo":"Práctica aplicada · 20 minutos orientativos","pregunta":"Diseña una prueba reversible de una mejora cotidiana. Define éxito, duración, esfuerzo, condición de suspensión y qué harás si no funciona.","ayuda":"Primera versión, contraste con el modelo y revisión propia."},{"tipo":"texto","texto":"<details><summary>Consultar modelo y retroalimentación</summary><p>Modelo: probar una agenda compartida durante dos semanas con un solo equipo; mantener respaldo del sistema anterior; suspender si impide registrar tareas. Un resultado negativo también es información útil.</p><p>Compara tu respuesta: identifica una condición explícita, una afirmación que necesita respaldo y una mejora concreta. El modelo es una posibilidad, no la única respuesta válida.</p></details>"},{"tipo":"texto","texto":"<h3>Reto del módulo · 90 minutos orientativos</h3><p>Analiza una objeción desde dos explicaciones alternativas. Propón qué pregunta o dato permitiría distinguirlas. Redacta un mensaje que pueda cambiar si aparece evidencia contraria.</p><p><strong>Entregable:</strong> Mapa de hipótesis, evidencia pendiente y dos versiones de mensaje.</p><p>Diagnóstico 15 min; primera versión 30; contraste 20; revisión 15; reflexión 10.</p>"},{"tipo":"reflexion","rotulo":"Bitácora del reto","pregunta":"Registra tu primera versión, una condición que faltaba y tu revisión justificada."},{"tipo":"texto","texto":"<h3>Autoevaluación del reto</h3><p>Revisa decisión clara, evidencia pertinente, condiciones explícitas y respeto al rechazo. En cada criterio: 0 ausente; 1 genérico; 2 concreto y justificado. Corrige los criterios con 0. Usa los modelos de las cuatro lecciones para contrastar tus decisiones.</p>"}],"minutosEstimados":45}],"quiz":{"titulo":"Evaluación de aplicación","preguntas":[{"p":"Una persona valora la independencia y rechaza supervisión diaria. ¿Qué distingue el caso?","ops":["Todas las personas independientes deciden igual.","Un valor puede influir en cómo interpreta una propuesta.","Su rechazo prueba falta de disciplina."],"correcta":1,"explica":"El valor orienta preferencias, sin determinar una conducta universal."},{"p":"El público tiene poco tiempo para leer. ¿Qué ajuste ayuda?","ops":["Mostrar idea principal, condiciones y detalle consultable.","Eliminar las condiciones importantes.","Añadir diez mensajes simultáneos."],"correcta":0,"explica":"Priorizar información facilita atención sin ocultar lo relevante."},{"p":"Un testimonio muy emotivo parece más convincente que datos amplios. ¿Qué revisarías?","ops":["Si la emoción garantiza que el caso es representativo.","Si debes descartar cualquier testimonio.","Si su vividez está sustituyendo la evaluación de evidencia."],"correcta":2,"explica":"Un ejemplo puede ser memorable sin representar la frecuencia real."},{"p":"Buscas sólo artículos que confirman tu propuesta. ¿Qué práctica corrige el sesgo?","ops":["Pedir opiniones únicamente a quienes ya están de acuerdo.","Examinar evidencia contraria y condiciones de fracaso.","Leer más veces los mismos argumentos."],"correcta":1,"explica":"Buscar refutaciones ayuda a calibrar la confianza."},{"p":"Después de invertir mucho en una idea, aparecen fallas. ¿Qué debe guiar la decisión siguiente?","ops":["Costos y beneficios futuros de continuar o cambiar.","La necesidad de justificar todo lo gastado.","El orgullo por mantener siempre la primera decisión."],"correcta":0,"explica":"El gasto pasado no vuelve conveniente una inversión futura."},{"p":"Una orden provoca resistencia. ¿Qué alternativa favorece autonomía?","ops":["Disfrazar la misma orden como falsa elección.","Culpar a la persona por resistirse.","Explicar razones y opciones reales de participación."],"correcta":2,"explica":"La autonomía requiere opciones auténticas y consecuencias claras."},{"p":"Una cifra inicial muy alta influye en una negociación. ¿Qué harías?","ops":["Responder con otra cifra sin fundamento.","Comparar con criterios independientes y alternativas.","Aceptar que la primera cifra define el valor justo."],"correcta":1,"explica":"Un ancla debe contrastarse con información pertinente."},{"p":"Un participante cambia de opinión tras nueva información. ¿Cómo interpretarlo?","ops":["Puede reflejar una actualización razonada.","Siempre demuestra debilidad.","Prueba que la opinión inicial era deshonesta."],"correcta":0,"explica":"Cambiar de criterio puede ser una respuesta adecuada a nueva evidencia."},{"p":"¿Qué afirmación sobre sesgos es prudente?","ops":["Permiten controlar cualquier decisión humana.","Afectan sólo a personas sin formación.","Son tendencias posibles que deben examinarse en contexto."],"correcta":2,"explica":"Conocer sesgos no da control infalible ni inmunidad personal."},{"p":"Una audiencia cansada omite detalles. ¿Qué diseño ayuda?","ops":["Usar cansancio para conseguir aceptación inmediata.","Dividir la explicación y confirmar comprensión de lo esencial.","Hablar más rápido para terminar todo."],"correcta":1,"explica":"La carga de atención exige facilitar comprensión, no aprovechar la fatiga."}]}},{"id":"pe-m04","titulo":"Argumentos, evidencia y pensamiento crítico","resumen":"Construye una propuesta de una página con dos fuentes identificadas, una objeción fuerte y una conclusión limitada a lo que la evidencia permite.","lecciones":[{"id":"pe-m04-l1","titulo":"Afirmaciones, razones y evidencia","objetivo":"Aplicar afirmaciones, razones y evidencia mediante un caso, una decisión comentada y una producción propia.","bloques":[{"tipo":"imagen","url":"recursos/diplomado-persuasion-etica/visuales/pe-m04.svg","pie":"Mapa del módulo: Afirmaciones, razones y evidencia; Evaluar fuentes; Cifras, comparación y causalidad; Contraargumentos y falacias"},{"tipo":"texto","texto":"<p>Una afirmación dice qué sostienes; una razón explica por qué debería aceptarse; la evidencia permite examinar esa razón. «Debemos cambiar el horario porque será mejor» repite la conclusión con otra palabra. Necesita explicar qué mejora, para quién y bajo qué condiciones.</p><p>Usa una estructura sencilla: propongo X, porque Y; observamos Z; esto respalda la propuesta si se cumple W. La última parte explicita un supuesto. Si el registro sólo incluye una semana atípica, ese supuesto merece revisión.</p><p>La evidencia puede ser cuantitativa o cualitativa, pero debe ser pertinente. Una entrevista ayuda a comprender una experiencia; no calcula por sí misma cuántas personas la comparten. Un promedio resume datos; puede ocultar diferencias importantes. Una conclusión responsable delimita población, periodo y resultado. Si la evidencia no basta, presenta la propuesta como hipótesis para probar, no como certeza establecida.</p>"},{"tipo":"tarjetas","rotulo":"Guía activa del módulo · anticipa, compara y repasa","voz":false,"tarjetas":[{"frente":"¿Cómo aplicarías «Afirmaciones, razones y evidencia»? Piensa en una acción concreta antes de voltear.","reverso":"Modelo: «En cinco entregas faltó un responsable asignado; propongo cerrar cada reunión nombrándolo». La evidencia apoya esa intervención específica mejor que una propuesta genérica de duplicar reuniones.","ej":"Al terminar el módulo, vuelve a esta tarjeta y formula tu propio ejemplo."},{"frente":"¿Cómo aplicarías «Evaluar fuentes»? Piensa en una acción concreta antes de voltear.","reverso":"Modelo: una encuesta interna sobre satisfacción no prueba una mejora causal en ventas. Puede respaldar que determinadas personas reportaron satisfacción en ese periodo, si se informa cómo se eligieron.","ej":"Al terminar el módulo, vuelve a esta tarjeta y formula tu propio ejemplo."},{"frente":"¿Cómo aplicarías «Cifras, comparación y causalidad»? Piensa en una acción concreta antes de voltear.","reverso":"Modelo: diez de cincuenta asistentes completan una práctica, después quince de cincuenta. El aumento es de cinco personas, diez puntos porcentuales o cincuenta por ciento relativo; esas expresiones no son intercambiables.","ej":"Al terminar el módulo, vuelve a esta tarjeta y formula tu propio ejemplo."},{"frente":"¿Cómo aplicarías «Contraargumentos y falacias»? Piensa en una acción concreta antes de voltear.","reverso":"Modelo: «Dos días no bastan para dominar la habilidad. El taller introduce el método y añade prácticas posteriores autogestivas; no lo anunciamos como dominio experto». Ajustar una promesa puede ser la respuesta más rigurosa.","ej":"Al terminar el módulo, vuelve a esta tarjeta y formula tu propio ejemplo."}]},{"tipo":"destacado","texto":"Caso ficticio: «Necesitamos más reuniones porque así estaremos mejor comunicados»."},{"tipo":"practica","rotulo":"Decide y contrasta","preguntas":[{"p":"¿Qué falta principalmente?","ops":["Explicar el problema observable y por qué más reuniones lo resolverían.","Repetir la frase con mayor seguridad.","Agregar que muchas empresas tienen reuniones."],"correcta":0,"explica":"La propuesta necesita una conexión examinable entre problema y solución. Popularidad o seguridad al hablar no demuestran esa conexión.","pista":"Revisa la restricción del caso y el efecto de tu respuesta sobre la decisión de la otra persona."}]},{"tipo":"completar","rotulo":"Recupera la idea clave","items":[{"frase":"La ___ permite examinar si una razón está respaldada.","resp":["evidencia"],"explica":"Relaciona este concepto con la decisión que acabas de analizar."}]},{"tipo":"reflexion","rotulo":"Práctica aplicada · 20 minutos orientativos","pregunta":"Elabora un argumento de cinco frases y subraya afirmación, razón, evidencia, supuesto y límite. Busca una frase que sólo repita la conclusión.","ayuda":"Primera versión, contraste con el modelo y revisión propia."},{"tipo":"texto","texto":"<details><summary>Consultar modelo y retroalimentación</summary><p>Modelo: «En cinco entregas faltó un responsable asignado; propongo cerrar cada reunión nombrándolo». La evidencia apoya esa intervención específica mejor que una propuesta genérica de duplicar reuniones.</p><p>Compara tu respuesta: identifica una condición explícita, una afirmación que necesita respaldo y una mejora concreta. El modelo es una posibilidad, no la única respuesta válida.</p></details>"}],"minutosEstimados":45},{"id":"pe-m04-l2","titulo":"Evaluar fuentes","objetivo":"Aplicar evaluar fuentes mediante un caso, una decisión comentada y una producción propia.","bloques":[{"tipo":"texto","texto":"<p>Una fuente conocida no garantiza que toda afirmación que se le atribuya sea correcta. Comprueba qué documento contiene el dato, quién lo produjo, cuándo, con qué método y para qué población. Diferencia la investigación original de un comentario que la resume.</p><p>Busca trazabilidad: un enlace identificable, el pasaje relevante y la relación con tu afirmación. Si una nota dice «los expertos aseguran» sin nombrar estudio, no la conviertas en evidencia sólida. Considera incentivos comerciales y posibles conflictos de interés sin descartar automáticamente todo dato financiado por una organización.</p><p>La actualidad importa de manera distinta según el tema. Una tarifa cambia con rapidez; un argumento histórico necesita contexto más que una fecha reciente. Contrasta fuentes independientes y explica desacuerdos. Si no puedes verificar un dato, retíralo o identifícalo como pendiente; no inventes una referencia para dar apariencia académica.</p>"},{"tipo":"destacado","texto":"Caso ficticio: una infografía afirma que un método duplica la productividad, pero no enlaza al estudio."},{"tipo":"practica","rotulo":"Decide y contrasta","preguntas":[{"p":"¿Qué harías antes de usarla?","ops":["Citar la infografía como demostración definitiva.","Cambiar el porcentaje por uno que parezca más creíble.","Buscar el estudio original y comprobar cómo se midió productividad."],"correcta":2,"explica":"Verificar el origen permite examinar el dato. Ajustar números intuitivamente sigue siendo fabricar evidencia.","pista":"Revisa la restricción del caso y el efecto de tu respuesta sobre la decisión de la otra persona."}]},{"tipo":"completar","rotulo":"Recupera la idea clave","items":[{"frase":"Poder localizar el origen de un dato aporta ___.","resp":["trazabilidad"],"explica":"Relaciona este concepto con la decisión que acabas de analizar."}]},{"tipo":"reflexion","rotulo":"Práctica aplicada · 20 minutos orientativos","pregunta":"Prepara dos fichas de fuente: autor, fecha, método o tipo de documento, afirmación respaldada, límites y enlace. Marca una que no usarías y explica por qué.","ayuda":"Primera versión, contraste con el modelo y revisión propia."},{"tipo":"texto","texto":"<details><summary>Consultar modelo y retroalimentación</summary><p>Modelo: una encuesta interna sobre satisfacción no prueba una mejora causal en ventas. Puede respaldar que determinadas personas reportaron satisfacción en ese periodo, si se informa cómo se eligieron.</p><p>Compara tu respuesta: identifica una condición explícita, una afirmación que necesita respaldo y una mejora concreta. El modelo es una posibilidad, no la única respuesta válida.</p></details>"},{"tipo":"relacionar","rotulo":"Relaciona el concepto con su aplicación","voz":false,"pares":[["Afirmación","La prueba redujo el tiempo medio en este equipo"],["Evidencia","Registro comparable de reuniones antes y después"],["Límite","No se asignaron los equipos al azar"],["Conclusión calibrada","Los datos son prometedores pero no garantizan el mismo efecto"]]},{"tipo":"texto","texto":"<p><strong>Contrasta tu razonamiento:</strong> después de relacionar, explica por qué cada ejemplo corresponde a ese concepto y escribe un contraejemplo. No basta memorizar la pareja: identifica la conducta observable que la distingue.</p>"}],"minutosEstimados":45},{"id":"pe-m04-l3","titulo":"Cifras, comparación y causalidad","objetivo":"Aplicar cifras, comparación y causalidad mediante un caso, una decisión comentada y una producción propia.","bloques":[{"tipo":"texto","texto":"<p>Un número necesita denominador y contexto. Pasar de dos a cuatro solicitudes es un aumento del cien por ciento, pero sólo dos solicitudes adicionales. Presentar ambos datos permite calibrar el tamaño del cambio.</p><p>Que dos hechos ocurran juntos no demuestra que uno cause al otro. Si las ventas suben después de cambiar un anuncio, también pudieron variar precio, temporada o distribución. Una comparación mejor intenta mantener condiciones similares y registrar diferencias relevantes. Sin ese control, comunica asociación o resultado observado, no causalidad segura.</p><p>Al usar promedios, revisa dispersión y casos que quedan fuera. Una media de respuesta rápida puede coexistir con algunos clientes que esperan demasiado. Describe periodo, muestra, pérdidas de información y qué no se midió. La precisión aparente de un decimal no arregla una medición débil. Usa cifras para facilitar decisiones, no para cerrar preguntas legítimas.</p>"},{"tipo":"destacado","texto":"Caso ficticio: después de publicar un video, hubo veinte ventas más; la misma semana comenzó una promoción de precio."},{"tipo":"practica","rotulo":"Decide y contrasta","preguntas":[{"p":"¿Qué conclusión está justificada?","ops":["La promoción demuestra que el video no tuvo ningún efecto.","Las ventas aumentaron, pero no podemos atribuir todo el cambio al video.","El video causó exactamente veinte ventas adicionales."],"correcta":1,"explica":"Hay factores concurrentes. El caso no permite asignar causalidad exclusiva ni descartar toda contribución del video.","pista":"Revisa la restricción del caso y el efecto de tu respuesta sobre la decisión de la otra persona."}]},{"tipo":"completar","rotulo":"Recupera la idea clave","items":[{"frase":"Para interpretar un porcentaje necesitas conocer el ___.","resp":["denominador"],"explica":"Relaciona este concepto con la decisión que acabas de analizar."}]},{"tipo":"reflexion","rotulo":"Práctica aplicada · 20 minutos orientativos","pregunta":"Inventa una comparación pequeña, calcula diferencia absoluta y relativa y escribe dos explicaciones alternativas. Indica qué medición adicional necesitarías.","ayuda":"Primera versión, contraste con el modelo y revisión propia."},{"tipo":"texto","texto":"<details><summary>Consultar modelo y retroalimentación</summary><p>Modelo: diez de cincuenta asistentes completan una práctica, después quince de cincuenta. El aumento es de cinco personas, diez puntos porcentuales o cincuenta por ciento relativo; esas expresiones no son intercambiables.</p><p>Compara tu respuesta: identifica una condición explícita, una afirmación que necesita respaldo y una mejora concreta. El modelo es una posibilidad, no la única respuesta válida.</p></details>"}],"minutosEstimados":45},{"id":"pe-m04-l4","titulo":"Contraargumentos y falacias","objetivo":"Aplicar contraargumentos y falacias mediante un caso, una decisión comentada y una producción propia.","bloques":[{"tipo":"texto","texto":"<p>Un contraargumento útil cuestiona la razón más fuerte de tu propuesta. No consiste en inventar una oposición absurda para derrotarla fácilmente. Formula la objeción de manera que una persona razonable que discrepe pueda reconocerla.</p><p>Al revisar errores, enfócate en el razonamiento: atacar a quien habla no responde a su dato; presentar dos únicas opciones puede ocultar otras; apelar a popularidad no demuestra conveniencia. Sin embargo, no uses nombres de falacias como sustituto de una explicación. Debes señalar qué conexión falta y cómo afecta la conclusión.</p><p>Responde concediendo lo que corresponda, aportando evidencia y ajustando alcance. Puedes descubrir que la objeción invalida tu propuesta. En ese caso, revisarla es una mejora, no una derrota personal. Distingue desacuerdo sobre hechos, prioridades y pronósticos: cada uno necesita una respuesta diferente.</p>"},{"tipo":"destacado","texto":"Caso ficticio: alguien objeta que un taller de dos días no permite practicar lo suficiente. El vendedor responde: «Sólo criticas porque eres negativo»."},{"tipo":"practica","rotulo":"Decide y contrasta","preguntas":[{"p":"¿Qué falla en la respuesta?","ops":["Ataca a la persona sin responder a la limitación de práctica.","Demuestra que la objeción sobre duración es falsa.","Resuelve el problema si el vendedor tiene experiencia."],"correcta":0,"explica":"La experiencia del vendedor no elimina la necesidad de explicar cómo se practicará. La objeción merece respuesta sobre diseño y límites.","pista":"Revisa la restricción del caso y el efecto de tu respuesta sobre la decisión de la otra persona."}]},{"tipo":"completar","rotulo":"Recupera la idea clave","items":[{"frase":"Un contraargumento fuerte cuestiona razones, no el valor personal del ___.","resp":["interlocutor"],"explica":"Relaciona este concepto con la decisión que acabas de analizar."}]},{"tipo":"reflexion","rotulo":"Práctica aplicada · 20 minutos orientativos","pregunta":"Escribe la mejor objeción a tu propuesta. Responde con una concesión, un dato verificable y un ajuste. Si no puedes responder, cambia la propuesta.","ayuda":"Primera versión, contraste con el modelo y revisión propia."},{"tipo":"texto","texto":"<details><summary>Consultar modelo y retroalimentación</summary><p>Modelo: «Dos días no bastan para dominar la habilidad. El taller introduce el método y añade prácticas posteriores autogestivas; no lo anunciamos como dominio experto». Ajustar una promesa puede ser la respuesta más rigurosa.</p><p>Compara tu respuesta: identifica una condición explícita, una afirmación que necesita respaldo y una mejora concreta. El modelo es una posibilidad, no la única respuesta válida.</p></details>"},{"tipo":"texto","texto":"<h3>Reto del módulo · 90 minutos orientativos</h3><p>Construye una propuesta de una página con dos fuentes identificadas, una objeción fuerte y una conclusión limitada a lo que la evidencia permite.</p><p><strong>Entregable:</strong> Mapa de argumento, ficha de fuentes y respuesta al contraargumento.</p><p>Diagnóstico 15 min; primera versión 30; contraste 20; revisión 15; reflexión 10.</p>"},{"tipo":"reflexion","rotulo":"Bitácora del reto","pregunta":"Registra tu primera versión, una condición que faltaba y tu revisión justificada."},{"tipo":"texto","texto":"<h3>Autoevaluación del reto</h3><p>Revisa decisión clara, evidencia pertinente, condiciones explícitas y respeto al rechazo. En cada criterio: 0 ausente; 1 genérico; 2 concreto y justificado. Corrige los criterios con 0. Usa los modelos de las cuatro lecciones para contrastar tus decisiones.</p>"}],"minutosEstimados":45}],"quiz":{"titulo":"Evaluación de aplicación","preguntas":[{"p":"Una campaña afirma que un método causa éxito porque sus usuarios mejoraron. ¿Qué falta examinar?","ops":["Otras causas posibles y un diseño que permita comparar.","Sólo si el anuncio parece profesional.","Si hay una historia emocionante."],"correcta":0,"explica":"La mejora observada por sí sola no demuestra causalidad."},{"p":"Un informe pasa de 2 a 4 incidentes. ¿Cómo comunicarlo?","ops":["Hubo un aumento enorme sin mostrar cifras.","Sólo mostrar 100% y omitir la base.","Se duplicaron: pasaron de 2 a 4, en el periodo indicado."],"correcta":2,"explica":"Las cifras absolutas dan contexto al cambio relativo."},{"p":"¿Qué fuente sostiene mejor una afirmación específica?","ops":["Un autor famoso hablando de otro campo.","Una fuente pertinente cuyo método y límites puedan revisarse.","La primera publicación que aparece."],"correcta":1,"explica":"La relevancia y el método importan junto con la autoría."},{"p":"Un argumento ataca la personalidad de quien discrepa. ¿Qué conviene hacer?","ops":["Volver a la afirmación y a sus razones.","Responder con otro ataque personal.","Dar por falsa su conclusión automáticamente."],"correcta":0,"explica":"Evaluar una proposición requiere examinar su apoyo, no sólo a quien la expresa."},{"p":"¿Qué distingue evidencia de conclusión?","ops":["Son exactamente lo mismo.","Toda conclusión es un hecho observado.","La evidencia aporta observaciones; la conclusión interpreta lo que sostienen."],"correcta":2,"explica":"Separarlas permite revisar si el salto argumental está justificado."},{"p":"Una encuesta incluye sólo clientes satisfechos. ¿Qué limitación señalarías?","ops":["Que ninguna encuesta puede aportar información.","La selección impide representar a todos los clientes.","El tamaño del logotipo."],"correcta":1,"explica":"La muestra puede excluir experiencias relevantes y sesgar la estimación."},{"p":"¿Qué contraargumento fortalece una revisión?","ops":["La objeción más sólida que una persona informada plantearía.","Una versión absurda y fácil de derrotar.","Una crítica inventada sin relación con la propuesta."],"correcta":0,"explica":"Responder a la objeción fuerte evita refutar una caricatura."},{"p":"Dos opciones se presentan como las únicas, pero existen otras. ¿Qué revisarías?","ops":["Si una opción tiene un nombre más atractivo.","Si conviene elegir rápido para evitar confusión.","Si se está creando una falsa disyuntiva."],"correcta":2,"explica":"Examinar alternativas impide limitar artificialmente la decisión."},{"p":"Una investigación no encuentra un efecto claro. ¿Qué frase es adecuada?","ops":["Podemos afirmar el efecto si creemos suficiente.","Estos datos no permiten afirmar el efecto propuesto.","Se ha probado que jamás existe efecto alguno."],"correcta":1,"explica":"La falta de resultado concluyente exige expresar incertidumbre con alcance preciso."},{"p":"Antes de usar una estadística, ¿qué contexto comprobarías?","ops":["Población, periodo, definición y método.","Únicamente el porcentaje.","El número de veces que se compartió."],"correcta":0,"explica":"Sin contexto, una cifra correcta puede apoyar una interpretación inadecuada."}]}},{"id":"pe-m05","titulo":"Credibilidad, confianza y compromisos","resumen":"Revisa una promesa comercial o profesional exagerada y conviértela en un compromiso concreto, verificable y limitado.","lecciones":[{"id":"pe-m05-l1","titulo":"Competencia y honestidad","objetivo":"Aplicar competencia y honestidad mediante un caso, una decisión comentada y una producción propia.","bloques":[{"tipo":"imagen","url":"recursos/diplomado-persuasion-etica/visuales/pe-m05.svg","pie":"Mapa del módulo: Competencia y honestidad; Credenciales y testimonios; Coherencia y compromisos verificables; Reconocer y reparar errores"},{"tipo":"texto","texto":"<p>La credibilidad no es una cualidad que debas afirmar repetidamente; se apoya en conductas y evidencia pertinentes. Puedes mostrar una muestra de trabajo, explicar tu proceso y reconocer lo que no sabes. La confianza no exige fingir certeza.</p><p>Separa experiencia propia, conocimiento documentado y opinión. Haber resuelto un caso no significa poder garantizar cualquier resultado. Una explicación honesta puede ser firme: «puedo entregar estos materiales en esta fecha; el impacto posterior dependerá también de su aplicación».</p><p>La claridad sobre límites ayuda a evitar expectativas incompatibles. No conviertas vulnerabilidad aparente en una técnica teatral: admitir un defecto pequeño mientras ocultas una condición importante no equivale a transparencia. Pregunta qué evidencia necesita el interlocutor y proporciónala cuando exista. Si no existe, propone una forma de comprobar capacidad antes de un compromiso mayor.</p>"},{"tipo":"tarjetas","rotulo":"Guía activa del módulo · anticipa, compara y repasa","voz":false,"tarjetas":[{"frente":"¿Cómo aplicarías «Competencia y honestidad»? Piensa en una acción concreta antes de voltear.","reverso":"Modelo: sustituye «experto infalible» por «he preparado estos tres tipos de materiales; aquí puedes revisar una muestra». Una muestra debe ser propia o contar con permiso para mostrarse.","ej":"Al terminar el módulo, vuelve a esta tarjeta y formula tu propio ejemplo."},{"frente":"¿Cómo aplicarías «Credenciales y testimonios»? Piensa en una acción concreta antes de voltear.","reverso":"Modelo: «En una práctica ficticia, Ana reorganiza su presentación» no puede convertirse en «Nuestros clientes aumentan sus ventas». La primera enseña un procedimiento; la segunda afirma un resultado comercial.","ej":"Al terminar el módulo, vuelve a esta tarjeta y formula tu propio ejemplo."},{"frente":"¿Cómo aplicarías «Coherencia y compromisos verificables»? Piensa en una acción concreta antes de voltear.","reverso":"Modelo: «Responderemos consultas de acceso por correo en dos días hábiles» especifica canal, tema y plazo. No equivale a tutoría académica permanente ni promete resolver cualquier situación en ese tiempo.","ej":"Al terminar el módulo, vuelve a esta tarjeta y formula tu propio ejemplo."},{"frente":"¿Cómo aplicarías «Reconocer y reparar errores»? Piensa en una acción concreta antes de voltear.","reverso":"Modelo: «El mensaje anterior indicó lunes por error. El acceso se habilita el miércoles. Si esa fecha no te funciona, estas son las opciones…». Las opciones deben existir; no inventes devoluciones o compensaciones fuera de tus condiciones reales.","ej":"Al terminar el módulo, vuelve a esta tarjeta y formula tu propio ejemplo."}]},{"tipo":"destacado","texto":"Caso ficticio: te preguntan si una capacitación garantiza que todos venderán más."},{"tipo":"practica","rotulo":"Decide y contrasta","preguntas":[{"p":"¿Qué respuesta es defendible?","ops":["Garantizar ventas para que la persona no pierda confianza.","Evitar toda explicación porque los resultados dependen del alumno.","Explicar qué habilidades se trabajan y cómo se evalúan, sin garantizar ventas individuales."],"correcta":2,"explica":"La primera opción delimita responsabilidad y conserva información útil. Ni una garantía falsa ni una evasión ayudan a evaluar la oferta.","pista":"Revisa la restricción del caso y el efecto de tu respuesta sobre la decisión de la otra persona."}]},{"tipo":"completar","rotulo":"Recupera la idea clave","items":[{"frase":"Reconocer límites no equivale a carecer de ___.","resp":["competencia"],"explica":"Relaciona este concepto con la decisión que acabas de analizar."}]},{"tipo":"reflexion","rotulo":"Práctica aplicada · 20 minutos orientativos","pregunta":"Escribe una presentación profesional de 120 palabras separando experiencia, evidencia de trabajo y límites. Elimina un adjetivo que no puedas sostener.","ayuda":"Primera versión, contraste con el modelo y revisión propia."},{"tipo":"texto","texto":"<details><summary>Consultar modelo y retroalimentación</summary><p>Modelo: sustituye «experto infalible» por «he preparado estos tres tipos de materiales; aquí puedes revisar una muestra». Una muestra debe ser propia o contar con permiso para mostrarse.</p><p>Compara tu respuesta: identifica una condición explícita, una afirmación que necesita respaldo y una mejora concreta. El modelo es una posibilidad, no la única respuesta válida.</p></details>"}],"minutosEstimados":45},{"id":"pe-m05-l2","titulo":"Credenciales y testimonios","objetivo":"Aplicar credenciales y testimonios mediante un caso, una decisión comentada y una producción propia.","bloques":[{"tipo":"texto","texto":"<p>Las credenciales deben describirse con su nombre y alcance real. Tomar un curso no equivale a obtener una licencia profesional ni a contar con aval institucional para todos tus servicios. Evita usar logotipos o nombres de instituciones de manera que sugieran una relación inexistente.</p><p>Un testimonio relata una experiencia; no demuestra que sea típica o que se repetirá. Identifica si hubo compensación y no edites una frase hasta cambiar su significado. Para usar datos o imágenes de una persona, revisa la autorización y comparte sólo lo necesario.</p><p>Al presentar resultados, incluye condiciones relevantes y evita elegir únicamente éxitos extraordinarios como si fueran el promedio. Si sólo cuentas con una experiencia, dilo. Un caso ficticio sirve para enseñar, pero debe etiquetarse como tal y no presentarse como cliente real.</p>"},{"tipo":"destacado","texto":"Caso ficticio: una alumna dice que disfrutó un taller. Quieres anunciar que el taller duplicó sus ingresos."},{"tipo":"practica","rotulo":"Decide y contrasta","preguntas":[{"p":"¿Qué puedes afirmar con esa declaración?","ops":["Que todas las personas tendrán su misma experiencia.","Que expresó satisfacción, si autoriza ese uso, sin atribuirle resultados que no mencionó.","Que duplicó ingresos porque satisfacción implica éxito económico."],"correcta":1,"explica":"El testimonio sólo respalda su contenido real. No autoriza inventar resultados ni generalizar a todos los participantes.","pista":"Revisa la restricción del caso y el efecto de tu respuesta sobre la decisión de la otra persona."}]},{"tipo":"completar","rotulo":"Recupera la idea clave","items":[{"frase":"Un caso inventado para enseñar debe identificarse como ___.","resp":["ficticio"],"explica":"Relaciona este concepto con la decisión que acabas de analizar."}]},{"tipo":"reflexion","rotulo":"Práctica aplicada · 20 minutos orientativos","pregunta":"Diseña una ficha de caso con contexto, resultado, límites y permiso requerido. Redacta una frase que sería incorrecto extraer de ella.","ayuda":"Primera versión, contraste con el modelo y revisión propia."},{"tipo":"texto","texto":"<details><summary>Consultar modelo y retroalimentación</summary><p>Modelo: «En una práctica ficticia, Ana reorganiza su presentación» no puede convertirse en «Nuestros clientes aumentan sus ventas». La primera enseña un procedimiento; la segunda afirma un resultado comercial.</p><p>Compara tu respuesta: identifica una condición explícita, una afirmación que necesita respaldo y una mejora concreta. El modelo es una posibilidad, no la única respuesta válida.</p></details>"},{"tipo":"relacionar","rotulo":"Relaciona el concepto con su aplicación","voz":false,"pares":[["Competencia","Mostrar un trabajo pertinente y verificable"],["Honestidad","Reconocer qué no has comprobado"],["Coherencia","Cumplir el plazo que acordaste"],["Reparación","Reconocer el incumplimiento y ofrecer una corrección concreta"]]},{"tipo":"texto","texto":"<p><strong>Contrasta tu razonamiento:</strong> después de relacionar, explica por qué cada ejemplo corresponde a ese concepto y escribe un contraejemplo. No basta memorizar la pareja: identifica la conducta observable que la distingue.</p>"}],"minutosEstimados":45},{"id":"pe-m05-l3","titulo":"Coherencia y compromisos verificables","objetivo":"Aplicar coherencia y compromisos verificables mediante un caso, una decisión comentada y una producción propia.","bloques":[{"tipo":"texto","texto":"<p>Un compromiso útil define acción, responsable, plazo y criterio de cumplimiento. «Te acompañaremos siempre» puede sonar bien, pero no explica canal, horario o alcance. Convertirlo en condiciones observables reduce interpretaciones incompatibles.</p><p>Promete lo que controlas y distingue dependencias. Puedes comprometerte a enviar un documento mañana; no controlar cuándo un tercero lo aprobará. Si necesitas información del interlocutor, explica cuándo y qué ocurre si llega después.</p><p>La coherencia se observa a lo largo del proceso: anuncio, conversación, pago, entrega y soporte deberían describir la misma oferta. Revisa dónde cambian términos sin explicación. No conviertas una aceptación pequeña en autorización para una obligación mayor. Cuando cambie el alcance, confirma el nuevo acuerdo de forma explícita.</p>"},{"tipo":"destacado","texto":"Caso ficticio: una persona acepta recibir un temario y después recibe una factura por el curso."},{"tipo":"practica","rotulo":"Decide y contrasta","preguntas":[{"p":"¿Qué ocurrió?","ops":["Se confundió permiso para recibir información con aceptación de compra.","Recibir información siempre implica aceptar el servicio.","La factura vuelve válido cualquier acuerdo anterior."],"correcta":0,"explica":"Cada compromiso tiene alcance. La aceptación de una acción informativa no autoriza un cobro ni una inscripción.","pista":"Revisa la restricción del caso y el efecto de tu respuesta sobre la decisión de la otra persona."}]},{"tipo":"completar","rotulo":"Recupera la idea clave","items":[{"frase":"Un compromiso debe definir acción, responsable, plazo y criterio de ___.","resp":["cumplimiento"],"explica":"Relaciona este concepto con la decisión que acabas de analizar."}]},{"tipo":"reflexion","rotulo":"Práctica aplicada · 20 minutos orientativos","pregunta":"Reescribe tres promesas vagas como compromisos verificables. Señala qué dependencias están fuera de tu control.","ayuda":"Primera versión, contraste con el modelo y revisión propia."},{"tipo":"texto","texto":"<details><summary>Consultar modelo y retroalimentación</summary><p>Modelo: «Responderemos consultas de acceso por correo en dos días hábiles» especifica canal, tema y plazo. No equivale a tutoría académica permanente ni promete resolver cualquier situación en ese tiempo.</p><p>Compara tu respuesta: identifica una condición explícita, una afirmación que necesita respaldo y una mejora concreta. El modelo es una posibilidad, no la única respuesta válida.</p></details>"}],"minutosEstimados":45},{"id":"pe-m05-l4","titulo":"Reconocer y reparar errores","objetivo":"Aplicar reconocer y reparar errores mediante un caso, una decisión comentada y una producción propia.","bloques":[{"tipo":"texto","texto":"<p>Cuando una promesa falla, empieza por describir qué ocurrió y qué efecto pudo tener. Evita disculpas condicionales que trasladan toda la responsabilidad a cómo se sintió la otra persona. Reconocer un error no exige aceptar afirmaciones que no has comprobado.</p><p>Separa reparación inmediata, investigación y prevención. Si enviaste un horario incorrecto, corrige el dato, avisa a quienes podrían depender de él y explica opciones viables. No prometas una solución imposible para terminar la conversación.</p><p>Una reparación debe ser proporcional y verificable. Aclara qué harás, cuándo y por qué canal confirmarás el cierre. Después revisa el proceso que produjo el fallo. La confianza no se recupera automáticamente con una frase de disculpa; se reconstruye mediante acciones que la otra persona puede comprobar.</p>"},{"tipo":"destacado","texto":"Caso ficticio: un correo anunció acceso el lunes, pero estará disponible el miércoles."},{"tipo":"practica","rotulo":"Decide y contrasta","preguntas":[{"p":"¿Qué respuesta asume el problema?","ops":["Decir «lamentamos que lo hayas entendido así».","Prometer acceso inmediato aunque sabes que no será posible.","Reconocer el dato incorrecto, informar la fecha real y explicar las opciones disponibles."],"correcta":2,"explica":"La primera respuesta corrige información y permite decidir. Las otras evaden el error o lo agravan con una promesa nueva.","pista":"Revisa la restricción del caso y el efecto de tu respuesta sobre la decisión de la otra persona."}]},{"tipo":"completar","rotulo":"Recupera la idea clave","items":[{"frase":"Reparar incluye corregir, comunicar y ___.","resp":["prevenir"],"explica":"Relaciona este concepto con la decisión que acabas de analizar."}]},{"tipo":"reflexion","rotulo":"Práctica aplicada · 20 minutos orientativos","pregunta":"Redacta un aviso de corrección de 150 palabras con hechos, efecto, acción, plazo y seguimiento. Elimina cualquier promesa que no controles.","ayuda":"Primera versión, contraste con el modelo y revisión propia."},{"tipo":"texto","texto":"<details><summary>Consultar modelo y retroalimentación</summary><p>Modelo: «El mensaje anterior indicó lunes por error. El acceso se habilita el miércoles. Si esa fecha no te funciona, estas son las opciones…». Las opciones deben existir; no inventes devoluciones o compensaciones fuera de tus condiciones reales.</p><p>Compara tu respuesta: identifica una condición explícita, una afirmación que necesita respaldo y una mejora concreta. El modelo es una posibilidad, no la única respuesta válida.</p></details>"},{"tipo":"texto","texto":"<h3>Reto del módulo · 90 minutos orientativos</h3><p>Revisa una promesa comercial o profesional exagerada y conviértela en un compromiso concreto, verificable y limitado.</p><p><strong>Entregable:</strong> Promesa corregida, condiciones y procedimiento de reparación.</p><p>Diagnóstico 15 min; primera versión 30; contraste 20; revisión 15; reflexión 10.</p>"},{"tipo":"reflexion","rotulo":"Bitácora del reto","pregunta":"Registra tu primera versión, una condición que faltaba y tu revisión justificada."},{"tipo":"texto","texto":"<h3>Autoevaluación del reto</h3><p>Revisa decisión clara, evidencia pertinente, condiciones explícitas y respeto al rechazo. En cada criterio: 0 ausente; 1 genérico; 2 concreto y justificado. Corrige los criterios con 0. Usa los modelos de las cuatro lecciones para contrastar tus decisiones.</p>"}],"minutosEstimados":45}],"quiz":{"titulo":"Evaluación de aplicación","preguntas":[{"p":"Una persona experta en un campo opina sobre otro. ¿Cómo valorar su recomendación?","ops":["Aceptar cualquier afirmación por su prestigio.","Rechazar todo lo que diga.","Revisar su experiencia pertinente y las pruebas aportadas."],"correcta":2,"explica":"La autoridad tiene alcance y no reemplaza la evidencia."},{"p":"Prometiste entregar el viernes y sabes que no llegarás. ¿Qué construye confianza?","ops":["Prometer otra fecha imposible para tranquilizar.","Avisar pronto, explicar el impacto y proponer un acuerdo viable.","Esperar a que te pregunten."],"correcta":1,"explica":"La reparación empieza por información oportuna y un compromiso realizable."},{"p":"Un testimonio describe un resultado excepcional. ¿Qué aclararías?","ops":["Que es un caso particular y no garantiza resultados similares.","Que todos obtendrán lo mismo.","Que sustituye cualquier dato agregado."],"correcta":0,"explica":"Un testimonio no establece la frecuencia ni garantiza resultados individuales."},{"p":"¿Cuál compromiso puede comprobarse?","ops":["Haré todo lo necesario pronto.","Puedes confiar en que siempre doy lo mejor.","Enviaré el resumen mañana antes de las 15:00."],"correcta":2,"explica":"Acción, plazo y alcance permiten verificar cumplimiento."},{"p":"No conoces la respuesta a una pregunta técnica. ¿Qué dices?","ops":["Afirmas que el detalle no importa.","No lo he verificado; indicaré qué revisar y cuándo responder.","Inventas una respuesta probable."],"correcta":1,"explica":"Reconocer un límite y gestionar la consulta es más preciso que fingir certeza."},{"p":"Una credencial está vencida. ¿Cómo presentarla?","ops":["Con su periodo y estado actual sin insinuar vigencia.","Como acreditación vigente.","Sin fecha para evitar confusión."],"correcta":0,"explica":"La presentación debe reflejar el alcance temporal real."},{"p":"¿Qué señal ayuda más a evaluar confiabilidad sostenida?","ops":["Sólo una voz segura.","Un título llamativo sin verificación.","Un historial pertinente de compromisos cumplidos y correcciones."],"correcta":2,"explica":"La conducta verificable aporta más que una apariencia de seguridad."},{"p":"Cometiste un error en una cifra difundida. ¿Qué reparación es adecuada?","ops":["Culpar al público por interpretarla mal.","Corregirla con visibilidad y explicar qué conclusiones cambia.","Cambiarla silenciosamente si nadie lo nota."],"correcta":1,"explica":"La corrección debe permitir revisar decisiones basadas en el dato anterior."},{"p":"¿Para qué sirve explicitar límites de servicio?","ops":["Alinear expectativas sobre lo que se ofrece y lo que requiere otra solución.","Disminuir toda confianza necesariamente.","Evitar cualquier responsabilidad por promesas."],"correcta":0,"explica":"Los límites concretos evitan expectativas que el servicio no puede cumplir."},{"p":"Un cliente pide algo fuera de tu competencia. ¿Qué harías?","ops":["Aceptar para no perder autoridad.","Usar una credencial no relacionada como garantía.","Explicar el límite y orientar hacia una evaluación adecuada."],"correcta":2,"explica":"La confianza no exige presentarse como competente en todo."}]}},{"id":"pe-m06","titulo":"Diseñar mensajes claros y completos","resumen":"Presenta la misma propuesta a tres interlocutores: una persona usuaria, quien autoriza presupuesto y quien ejecuta el trabajo. Conserva hechos y condiciones; adapta el orden y los ejemplos.","lecciones":[{"id":"pe-m06-l1","titulo":"Idea central y estructura","objetivo":"Aplicar idea central y estructura mediante un caso, una decisión comentada y una producción propia.","bloques":[{"tipo":"imagen","url":"recursos/diplomado-persuasion-etica/visuales/pe-m06.svg","pie":"Mapa del módulo: Idea central y estructura; Lenguaje concreto y comprensible; Beneficios, costos y alternativas; Encuadres honestos"},{"tipo":"texto","texto":"<p>Antes de elegir palabras, define la decisión que quieres facilitar. «Informar sobre nuestro proyecto» es demasiado amplio; «decidir si probamos el sistema con un equipo durante una semana» delimita una acción. Resume esa decisión en una frase que otra persona pueda repetir.</p><p>Organiza el mensaje en apertura, razón, evidencia, condiciones y siguiente paso. No todas las conversaciones siguen exactamente ese orden, pero los elementos deben poder localizarse. Si incluyes tres peticiones distintas, indica su prioridad y cuáles pueden resolverse por separado.</p><p>Revisa cada párrafo preguntando qué función cumple. Un dato interesante puede distraer si no ayuda a valorar la propuesta. Eliminarlo no significa ocultar información relevante: puedes trasladar detalles secundarios a un anexo accesible. Prueba el mensaje con una pregunta de comprensión: «¿qué entendiste que estamos proponiendo?». La respuesta revela diferencias que una simple pregunta de aprobación puede esconder.</p>"},{"tipo":"tarjetas","rotulo":"Guía activa del módulo · anticipa, compara y repasa","voz":false,"tarjetas":[{"frente":"¿Cómo aplicarías «Idea central y estructura»? Piensa en una acción concreta antes de voltear.","reverso":"Modelo: apertura con la prueba propuesta; razón sobre el problema; evidencia observada; costo y plazo; pregunta sobre autorización. Un saludo largo no debe desplazar la información necesaria.","ej":"Al terminar el módulo, vuelve a esta tarjeta y formula tu propio ejemplo."},{"frente":"¿Cómo aplicarías «Lenguaje concreto y comprensible»? Piensa en una acción concreta antes de voltear.","reverso":"Modelo: «acompañamiento completo» puede convertirse en «guía escrita, ejercicios con respuestas y correo para problemas de acceso», si eso es lo que realmente se incluye.","ej":"Al terminar el módulo, vuelve a esta tarjeta y formula tu propio ejemplo."},{"frente":"¿Cómo aplicarías «Beneficios, costos y alternativas»? Piensa en una acción concreta antes de voltear.","reverso":"Modelo: para estudiar una habilidad, compara curso autogestivo, tutoría y recursos abiertos. El apoyo humano y la flexibilidad son diferencias de servicio; no deben ocultarse detrás de un único precio.","ej":"Al terminar el módulo, vuelve a esta tarjeta y formula tu propio ejemplo."},{"frente":"¿Cómo aplicarías «Encuadres honestos»? Piensa en una acción concreta antes de voltear.","reverso":"Modelo: para respaldar archivos, «reduce el riesgo de perder trabajo» debe acompañarse de frecuencia, ubicación y prueba de recuperación. No promete que ningún incidente pueda ocurrir.","ej":"Al terminar el módulo, vuelve a esta tarjeta y formula tu propio ejemplo."}]},{"tipo":"destacado","texto":"Caso ficticio: un correo mezcla invitación a una reunión, compra de software y cambio de horario, sin indicar qué debe contestarse."},{"tipo":"practica","rotulo":"Decide y contrasta","preguntas":[{"p":"¿Cómo lo mejorarías?","ops":["Pedir que respondan «acepto» a todo el mensaje.","Separar las decisiones y destacar qué respuesta se necesita primero.","Añadir urgencia al asunto sin cambiar el contenido."],"correcta":1,"explica":"Separar decisiones permite aceptar una y rechazar otra. Una aceptación global puede ocultar desacuerdos importantes.","pista":"Revisa la restricción del caso y el efecto de tu respuesta sobre la decisión de la otra persona."}]},{"tipo":"completar","rotulo":"Recupera la idea clave","items":[{"frase":"La idea central debe identificar la ___ que se quiere facilitar.","resp":["decisión"],"explica":"Relaciona este concepto con la decisión que acabas de analizar."}]},{"tipo":"reflexion","rotulo":"Práctica aplicada · 20 minutos orientativos","pregunta":"Organiza un correo de cinco párrafos. Escribe al margen la función de cada uno y elimina cualquier párrafo sin función clara.","ayuda":"Primera versión, contraste con el modelo y revisión propia."},{"tipo":"texto","texto":"<details><summary>Consultar modelo y retroalimentación</summary><p>Modelo: apertura con la prueba propuesta; razón sobre el problema; evidencia observada; costo y plazo; pregunta sobre autorización. Un saludo largo no debe desplazar la información necesaria.</p><p>Compara tu respuesta: identifica una condición explícita, una afirmación que necesita respaldo y una mejora concreta. El modelo es una posibilidad, no la única respuesta válida.</p></details>"}],"minutosEstimados":45},{"id":"pe-m06-l2","titulo":"Lenguaje concreto y comprensible","objetivo":"Aplicar lenguaje concreto y comprensible mediante un caso, una decisión comentada y una producción propia.","bloques":[{"tipo":"texto","texto":"<p>Palabras como integral, innovador o estratégico no explican qué recibirá alguien. Sustituye abstracciones por acciones observables: «organizarás pendientes en una agenda semanal» informa más que «transformarás tu productividad».</p><p>Usa verbos, ejemplos y unidades claras. Si necesitas un término técnico, explícalo en su primera aparición y comprueba que sea relevante. No simplifiques hasta deformar la idea: una explicación sencilla puede reconocer excepciones y límites.</p><p>Revisa longitud de frases, referencias ambiguas y dobles negaciones. «Esto se hará después» necesita especificar qué y cuándo. Leer en voz alta ayuda a detectar frases difíciles, pero no garantiza comprensión para todas las personas. Ofrece texto accesible, ejemplos alternativos y una forma de preguntar. El lenguaje claro permite examinar una propuesta, no sólo recordarla.</p>"},{"tipo":"destacado","texto":"Caso ficticio: un anuncio promete «una solución holística de optimización de interacciones»."},{"tipo":"practica","rotulo":"Decide y contrasta","preguntas":[{"p":"¿Qué alternativa informa mejor?","ops":["Practicarás preguntas, escucha y respuestas a objeciones mediante casos.","Una experiencia disruptiva de excelencia comunicacional.","La mejor solución integral para todos."],"correcta":0,"explica":"La alternativa concreta describe acciones y método. Los adjetivos comparativos necesitan criterios y no sustituyen información.","pista":"Revisa la restricción del caso y el efecto de tu respuesta sobre la decisión de la otra persona."}]},{"tipo":"completar","rotulo":"Recupera la idea clave","items":[{"frase":"El lenguaje concreto describe acciones ___.","resp":["observables"],"explica":"Relaciona este concepto con la decisión que acabas de analizar."}]},{"tipo":"reflexion","rotulo":"Práctica aplicada · 20 minutos orientativos","pregunta":"Reescribe diez expresiones vagas de una oferta inventada. Para cada una, especifica una conducta, un producto o una condición verificable.","ayuda":"Primera versión, contraste con el modelo y revisión propia."},{"tipo":"texto","texto":"<details><summary>Consultar modelo y retroalimentación</summary><p>Modelo: «acompañamiento completo» puede convertirse en «guía escrita, ejercicios con respuestas y correo para problemas de acceso», si eso es lo que realmente se incluye.</p><p>Compara tu respuesta: identifica una condición explícita, una afirmación que necesita respaldo y una mejora concreta. El modelo es una posibilidad, no la única respuesta válida.</p></details>"},{"tipo":"relacionar","rotulo":"Relaciona el concepto con su aplicación","voz":false,"pares":[["Petición concreta","Probar la agenda durante dos reuniones"],["Costo visible","Reservar diez minutos de preparación"],["Alternativa","Enviar los temas por escrito antes de la reunión"],["Criterio de revisión","Comparar duración y acuerdos al finalizar la prueba"]]},{"tipo":"texto","texto":"<p><strong>Contrasta tu razonamiento:</strong> después de relacionar, explica por qué cada ejemplo corresponde a ese concepto y escribe un contraejemplo. No basta memorizar la pareja: identifica la conducta observable que la distingue.</p>"}],"minutosEstimados":45},{"id":"pe-m06-l3","titulo":"Beneficios, costos y alternativas","objetivo":"Aplicar beneficios, costos y alternativas mediante un caso, una decisión comentada y una producción propia.","bloques":[{"tipo":"texto","texto":"<p>Una característica describe lo que una oferta tiene; un beneficio explica qué podría aportar en una situación concreta. «Incluye plantillas» es una característica; «las plantillas ayudan a preparar un primer borrador» describe un uso posible. No equivale a garantizar ahorro de tiempo para todas las personas.</p><p>Presenta también costos: dinero, esfuerzo, aprendizaje, mantenimiento y renuncia a otras opciones. Compara alternativas sobre los mismos criterios. No enfrentes el mejor escenario de tu propuesta con el peor de la competencia. Incluye la posibilidad de conservar la situación actual cuando sea razonable.</p><p>Una comparación honesta puede concluir que tu oferta no conviene. Eso ayuda a evitar expectativas incompatibles y decisiones apresuradas. Aclara qué datos son conocidos, cuáles estimados y quién debe confirmarlos. Si un costo no aplica a todos, explica la condición en lugar de esconderlo o sumarlo indiscriminadamente.</p>"},{"tipo":"destacado","texto":"Caso ficticio: una herramienta tiene precio mensual bajo, pero requiere una configuración inicial costosa."},{"tipo":"practica","rotulo":"Decide y contrasta","preguntas":[{"p":"¿Qué comparación es útil?","ops":["Comparar sólo la mensualidad propia con el costo total de otra herramienta.","Omitir configuración porque se paga una sola vez.","Mostrar costo inicial y recurrente junto con esfuerzo y alternativas equivalentes."],"correcta":2,"explica":"Las comparaciones necesitan el mismo horizonte y conceptos. Un pago único sigue formando parte del costo de la decisión.","pista":"Revisa la restricción del caso y el efecto de tu respuesta sobre la decisión de la otra persona."}]},{"tipo":"completar","rotulo":"Recupera la idea clave","items":[{"frase":"Una comparación justa utiliza los mismos ___ para todas las opciones.","resp":["criterios"],"explica":"Relaciona este concepto con la decisión que acabas de analizar."}]},{"tipo":"reflexion","rotulo":"Práctica aplicada · 20 minutos orientativos","pregunta":"Construye una tabla de tres alternativas para una tarea cotidiana: costo, tiempo, ventajas, límites y opción de no cambiar. Señala una estimación pendiente.","ayuda":"Primera versión, contraste con el modelo y revisión propia."},{"tipo":"texto","texto":"<details><summary>Consultar modelo y retroalimentación</summary><p>Modelo: para estudiar una habilidad, compara curso autogestivo, tutoría y recursos abiertos. El apoyo humano y la flexibilidad son diferencias de servicio; no deben ocultarse detrás de un único precio.</p><p>Compara tu respuesta: identifica una condición explícita, una afirmación que necesita respaldo y una mejora concreta. El modelo es una posibilidad, no la única respuesta válida.</p></details>"}],"minutosEstimados":45},{"id":"pe-m06-l4","titulo":"Encuadres honestos","objetivo":"Aplicar encuadres honestos mediante un caso, una decisión comentada y una producción propia.","bloques":[{"tipo":"texto","texto":"<p>El encuadre selecciona desde qué perspectiva se presenta información. «Ahorra diez minutos» y «evita perder diez minutos» pueden describir el mismo cambio, pero dirigir la atención de manera distinta. Utiliza ese recurso sin alterar el dato ni exagerar sus consecuencias.</p><p>Revisa qué queda fuera del marco. Presentar sólo beneficios puede ocultar esfuerzo; presentar sólo riesgos puede provocar una impresión desproporcionada. Ofrece contexto suficiente y evita asociar una decisión pequeña con el valor total de una persona.</p><p>Un buen ejercicio consiste en escribir el mismo dato desde dos perspectivas y comprobar que ambas sean compatibles. Si una versión cambia denominador, periodo o condiciones, no es sólo un cambio de encuadre: cambió la información. Cuando uses comparaciones, explica la base. No presentes una opción como única salida si existen alternativas relevantes.</p>"},{"tipo":"destacado","texto":"Caso ficticio: de cien participantes, ochenta completaron una actividad. Quieres destacar el resultado."},{"tipo":"practica","rotulo":"Decide y contrasta","preguntas":[{"p":"¿Qué frase conserva el dato?","ops":["Sólo quien no se esfuerza queda fuera del ochenta por ciento.","Ochenta de cien la completaron; veinte no, y falta conocer los motivos.","El método garantiza completar cualquier actividad."],"correcta":1,"explica":"El dato describe un resultado, no una garantía ni una causa del abandono. El encuadre no autoriza agregar explicaciones sin evidencia.","pista":"Revisa la restricción del caso y el efecto de tu respuesta sobre la decisión de la otra persona."}]},{"tipo":"completar","rotulo":"Recupera la idea clave","items":[{"frase":"Cambiar la perspectiva sin alterar datos es un cambio de ___.","resp":["encuadre"],"explica":"Relaciona este concepto con la decisión que acabas de analizar."}]},{"tipo":"reflexion","rotulo":"Práctica aplicada · 20 minutos orientativos","pregunta":"Escribe una versión orientada al beneficio y otra al riesgo de una propuesta. Añade una versión equilibrada con condiciones y alternativas.","ayuda":"Primera versión, contraste con el modelo y revisión propia."},{"tipo":"texto","texto":"<details><summary>Consultar modelo y retroalimentación</summary><p>Modelo: para respaldar archivos, «reduce el riesgo de perder trabajo» debe acompañarse de frecuencia, ubicación y prueba de recuperación. No promete que ningún incidente pueda ocurrir.</p><p>Compara tu respuesta: identifica una condición explícita, una afirmación que necesita respaldo y una mejora concreta. El modelo es una posibilidad, no la única respuesta válida.</p></details>"},{"tipo":"texto","texto":"<h3>Reto del módulo · 90 minutos orientativos</h3><p>Presenta la misma propuesta a tres interlocutores: una persona usuaria, quien autoriza presupuesto y quien ejecuta el trabajo. Conserva hechos y condiciones; adapta el orden y los ejemplos.</p><p><strong>Entregable:</strong> Tres mensajes de 150 palabras y tabla de elementos invariantes.</p><p>Diagnóstico 15 min; primera versión 30; contraste 20; revisión 15; reflexión 10.</p>"},{"tipo":"reflexion","rotulo":"Bitácora del reto","pregunta":"Registra tu primera versión, una condición que faltaba y tu revisión justificada."},{"tipo":"texto","texto":"<h3>Autoevaluación del reto</h3><p>Revisa decisión clara, evidencia pertinente, condiciones explícitas y respeto al rechazo. En cada criterio: 0 ausente; 1 genérico; 2 concreto y justificado. Corrige los criterios con 0. Usa los modelos de las cuatro lecciones para contrastar tus decisiones.</p>"}],"minutosEstimados":45}],"quiz":{"titulo":"Evaluación de aplicación","preguntas":[{"p":"Una propuesta comienza con cinco páginas de contexto y oculta la petición. ¿Qué mejorarías?","ops":["Reemplazar la petición por un eslogan.","Presentar temprano la decisión solicitada y ordenar su apoyo.","Añadir más antecedentes al inicio."],"correcta":1,"explica":"La estructura debe facilitar identificar qué se pide y por qué."},{"p":"¿Cuál frase es más concreta?","ops":["Entregaremos dos reportes mensuales durante tres meses.","Ofrecemos soluciones de alto impacto.","Transformaremos todo tu potencial."],"correcta":0,"explica":"La primera permite entender y comprobar el alcance."},{"p":"Un beneficio depende de dedicar dos horas semanales. ¿Qué conviene mostrar?","ops":["Sólo el beneficio en el anuncio principal.","La condición después de la contratación.","El beneficio esperado junto con esa condición."],"correcta":2,"explica":"Una condición necesaria forma parte de la decisión."},{"p":"Dos planes tienen costos y límites distintos. ¿Cómo compararlos?","ops":["Usando unidades diferentes para dificultar la comparación.","Con los mismos criterios, incluidos costos y restricciones.","Con beneficios del propio y defectos del otro."],"correcta":1,"explica":"Criterios consistentes permiten una comparación útil."},{"p":"¿Qué hace un buen resumen ejecutivo?","ops":["Expone propuesta, fundamento, impacto y siguiente paso.","Elimina toda incertidumbre.","Repite el título varias veces."],"correcta":0,"explica":"El resumen orienta la decisión sin sustituir condiciones esenciales."},{"p":"Un mensaje afirma 90% de éxito. ¿Qué pregunta ayuda a interpretar el encuadre?","ops":["Qué color acompaña al porcentaje.","Si 90 parece un número suficientemente alto.","Qué significa éxito, sobre cuántos casos y en qué periodo."],"correcta":2,"explica":"El encuadre requiere definiciones y base para evitar impresiones engañosas."},{"p":"La propuesta usa términos internos que el público desconoce. ¿Qué ajuste harías?","ops":["Eliminar el detalle necesario para decidir.","Definirlos o reemplazarlos con lenguaje familiar preciso.","Añadir más siglas para mostrar experiencia."],"correcta":1,"explica":"Claridad no equivale a imprecisión; exige explicar los conceptos."},{"p":"¿Cuál siguiente paso reduce ambigüedad?","ops":["Revisa el documento y envía tus dudas antes del jueves.","Lo vemos luego.","Actúa ya."],"correcta":0,"explica":"Un paso concreto especifica acción y plazo comprensible."},{"p":"¿Qué costo puede ser relevante además del precio?","ops":["Sólo el dinero cuenta como costo.","Ningún costo si la intención es ayudar.","Tiempo, esfuerzo y cambios de operación."],"correcta":2,"explica":"La decisión puede depender de recursos no monetarios."},{"p":"¿Cómo comprobar claridad antes de publicar?","ops":["Contar cuántas palabras técnicas contiene.","Pedir a alguien que explique con sus palabras acción y condiciones.","Preguntar sólo si le gustaron los colores."],"correcta":1,"explica":"La recuperación de significado revela problemas de comprensión."}]}},{"id":"pe-m07","titulo":"Historias, emoción y ejemplos responsables","resumen":"Escribe una historia de 300 palabras que ilustre una decisión y acompáñala de evidencia independiente, límites y una alternativa. Identifica claramente que es ficticia.","lecciones":[{"id":"pe-m07-l1","titulo":"Escena, tensión y resolución","objetivo":"Aplicar escena, tensión y resolución mediante un caso, una decisión comentada y una producción propia.","bloques":[{"tipo":"imagen","url":"recursos/diplomado-persuasion-etica/visuales/pe-m07.svg","pie":"Mapa del módulo: Escena, tensión y resolución; Historia y evidencia cumplen funciones distintas; Emoción sin explotación; Casos, testimonios y consentimiento"},{"tipo":"texto","texto":"<p>Una historia organiza una experiencia alrededor de una situación, una dificultad y una decisión. Para enseñar no necesitas una transformación extraordinaria: un error cotidiano permite mostrar cómo se aplica una herramienta.</p><p>Define quién necesita hacer qué, qué obstáculo encuentra, qué opciones considera y qué consecuencia observa. La resolución no tiene que ser perfecta. Una historia que reconoce un costo o una duda puede preparar mejor para situaciones reales que una secuencia en la que todo sale bien.</p><p>Elimina detalles que no ayudan a entender la decisión, pero conserva los necesarios para interpretarla. Si inventas nombres y acontecimientos, indica que se trata de un caso ficticio. Evita usar personas reconocibles sin autorización. Una historia sirve para ilustrar un mecanismo o una pregunta; no demuestra por sí misma que la solución funcionará para todos.</p>"},{"tipo":"tarjetas","rotulo":"Guía activa del módulo · anticipa, compara y repasa","voz":false,"tarjetas":[{"frente":"¿Cómo aplicarías «Escena, tensión y resolución»? Piensa en una acción concreta antes de voltear.","reverso":"Modelo: una vecina propone otro horario, descubre una restricción, modifica la propuesta y acuerdan probarla. El aprendizaje puede ser escuchar antes de cerrar, aunque no todos prefieran el nuevo horario.","ej":"Al terminar el módulo, vuelve a esta tarjeta y formula tu propio ejemplo."},{"frente":"¿Cómo aplicarías «Historia y evidencia cumplen funciones distintas»? Piensa en una acción concreta antes de voltear.","reverso":"Modelo: si alguien mejora su presentación, pregunta cómo se evaluó, con qué criterio y qué más practicó. El relato orienta qué investigar, no sustituye esa investigación.","ej":"Al terminar el módulo, vuelve a esta tarjeta y formula tu propio ejemplo."},{"frente":"¿Cómo aplicarías «Emoción sin explotación»? Piensa en una acción concreta antes de voltear.","reverso":"Modelo: «Prepara una presentación de tres minutos con una guía y práctica» permite anticipar una actividad. No necesita afirmar que quien aún no sabe hacerlo vale menos.","ej":"Al terminar el módulo, vuelve a esta tarjeta y formula tu propio ejemplo."},{"frente":"¿Cómo aplicarías «Casos, testimonios y consentimiento»? Piensa en una acción concreta antes de voltear.","reverso":"Modelo: distinguir una cita en un informe privado de una publicación comercial. La ficha sirve para identificar preguntas pendientes; no sustituye los procedimientos legales de la organización.","ej":"Al terminar el módulo, vuelve a esta tarjeta y formula tu propio ejemplo."}]},{"tipo":"destacado","texto":"Caso ficticio: una coordinadora reduce un correo de cuatro páginas a una propuesta con anexos y recibe preguntas más específicas."},{"tipo":"practica","rotulo":"Decide y contrasta","preguntas":[{"p":"¿Qué hace útil la historia?","ops":["Mostrar el problema, el cambio concreto y sus límites.","Afirmar que cualquier correo breve logra aprobación.","Agregar un final espectacular aunque no sea parte del caso."],"correcta":0,"explica":"La historia permite observar una decisión. No convierte una experiencia aislada en una regla universal.","pista":"Revisa la restricción del caso y el efecto de tu respuesta sobre la decisión de la otra persona."}]},{"tipo":"completar","rotulo":"Recupera la idea clave","items":[{"frase":"Una historia educativa muestra situación, dificultad, decisión y ___.","resp":["consecuencia"],"explica":"Relaciona este concepto con la decisión que acabas de analizar."}]},{"tipo":"reflexion","rotulo":"Práctica aplicada · 20 minutos orientativos","pregunta":"Escribe una historia de seis frases sobre una decisión de comunicación. Subraya qué elemento cambia gracias a una acción concreta.","ayuda":"Primera versión, contraste con el modelo y revisión propia."},{"tipo":"texto","texto":"<details><summary>Consultar modelo y retroalimentación</summary><p>Modelo: una vecina propone otro horario, descubre una restricción, modifica la propuesta y acuerdan probarla. El aprendizaje puede ser escuchar antes de cerrar, aunque no todos prefieran el nuevo horario.</p><p>Compara tu respuesta: identifica una condición explícita, una afirmación que necesita respaldo y una mejora concreta. El modelo es una posibilidad, no la única respuesta válida.</p></details>"}],"minutosEstimados":45},{"id":"pe-m07-l2","titulo":"Historia y evidencia cumplen funciones distintas","objetivo":"Aplicar historia y evidencia cumplen funciones distintas mediante un caso, una decisión comentada y una producción propia.","bloques":[{"tipo":"texto","texto":"<p>Una historia puede hacer visible una experiencia; la evidencia permite evaluar cuánto respalda una conclusión. Confundir ambas funciones produce generalizaciones: «una persona logró esto» no significa «este método produce ese resultado en cualquier participante».</p><p>Después de una historia, formula la pregunta que abre y explica qué información adicional necesitarías. Puedes contrastar casos con resultados distintos. No uses un caso de fracaso sólo para culpar a quien no obtuvo el resultado deseado; considera condiciones y limitaciones del método.</p><p>Cuando presentes datos junto a una historia, conserva trazabilidad y no adaptes los números para que encajen con el relato. Si el caso es ficticio, los datos ilustrativos también deben estar identificados. La narrativa puede guiar la atención, pero la conclusión debe ajustarse al respaldo disponible.</p>"},{"tipo":"destacado","texto":"Caso ficticio: un alumno dice que después de un taller consiguió empleo. No se conoce qué otros factores influyeron."},{"tipo":"practica","rotulo":"Decide y contrasta","preguntas":[{"p":"¿Qué conclusión permite el caso?","ops":["El taller garantiza empleo a cualquier participante.","Su experiencia no merece escucharse porque no es un experimento.","Describe su experiencia, pero no demuestra que el taller cause empleo para todos."],"correcta":2,"explica":"Una experiencia tiene valor descriptivo sin probar causalidad general. Reconocer ese límite evita exagerar y también evita despreciar el relato.","pista":"Revisa la restricción del caso y el efecto de tu respuesta sobre la decisión de la otra persona."}]},{"tipo":"completar","rotulo":"Recupera la idea clave","items":[{"frase":"Un caso individual no demuestra una conclusión ___.","resp":["universal"],"explica":"Relaciona este concepto con la decisión que acabas de analizar."}]},{"tipo":"reflexion","rotulo":"Práctica aplicada · 20 minutos orientativos","pregunta":"Acompaña una historia con una pregunta de investigación y dos datos necesarios para responderla. Escribe una conclusión provisional prudente.","ayuda":"Primera versión, contraste con el modelo y revisión propia."},{"tipo":"texto","texto":"<details><summary>Consultar modelo y retroalimentación</summary><p>Modelo: si alguien mejora su presentación, pregunta cómo se evaluó, con qué criterio y qué más practicó. El relato orienta qué investigar, no sustituye esa investigación.</p><p>Compara tu respuesta: identifica una condición explícita, una afirmación que necesita respaldo y una mejora concreta. El modelo es una posibilidad, no la única respuesta válida.</p></details>"},{"tipo":"relacionar","rotulo":"Relaciona el concepto con su aplicación","voz":false,"pares":[["Escena","Una persona llega a una reunión sin saber qué decidir"],["Tensión","El equipo tiene dos prioridades incompatibles"],["Resolución","Se acuerda un criterio para ordenar los temas"],["Límite del relato","La experiencia de un equipo no demuestra un efecto universal"]]},{"tipo":"texto","texto":"<p><strong>Contrasta tu razonamiento:</strong> después de relacionar, explica por qué cada ejemplo corresponde a ese concepto y escribe un contraejemplo. No basta memorizar la pareja: identifica la conducta observable que la distingue.</p>"}],"minutosEstimados":45},{"id":"pe-m07-l3","titulo":"Emoción sin explotación","objetivo":"Aplicar emoción sin explotación mediante un caso, una decisión comentada y una producción propia.","bloques":[{"tipo":"texto","texto":"<p>Las decisiones pueden involucrar esperanza, preocupación, orgullo o frustración. Hablar de esas emociones no es por sí mismo incorrecto. El cuidado está en no exagerar riesgos, humillar o presentar una compra como única forma de recuperar dignidad o pertenencia.</p><p>Describe consecuencias proporcionadas y ofrece capacidad de acción. «Podemos practicar cómo organizar tus ideas» es distinto de «si no compras, siempre harás el ridículo». La primera invita a trabajar una habilidad; la segunda convierte una dificultad en identidad permanente.</p><p>Al revisar un mensaje, pregúntate si la emoción ayuda a comprender o impide examinar condiciones. Si la persona está muy alterada, puede convenir posponer una decisión comercial. No prometas tratamientos psicológicos o resultados clínicos cuando ofreces formación en comunicación. Mantén la relación entre el problema descrito y lo que realmente se enseña.</p>"},{"tipo":"destacado","texto":"Caso ficticio: promocionas un curso para hablar en público a alguien que teme equivocarse."},{"tipo":"practica","rotulo":"Decide y contrasta","preguntas":[{"p":"¿Qué mensaje mantiene proporción?","ops":["Si no te inscribes, perderás todas tus oportunidades.","Practicaremos estructuras y ensayos; equivocarse forma parte del aprendizaje.","Compra para dejar de ser una persona insegura para siempre."],"correcta":1,"explica":"La primera opción describe trabajo concreto. Las otras convierten la formación en una promesa total o en una amenaza desproporcionada.","pista":"Revisa la restricción del caso y el efecto de tu respuesta sobre la decisión de la otra persona."}]},{"tipo":"completar","rotulo":"Recupera la idea clave","items":[{"frase":"Las consecuencias comunicadas deben ser ___ al problema real.","resp":["proporcionadas"],"explica":"Relaciona este concepto con la decisión que acabas de analizar."}]},{"tipo":"reflexion","rotulo":"Práctica aplicada · 20 minutos orientativos","pregunta":"Reescribe un anuncio que use vergüenza. Mantén un beneficio concreto sin atacar identidad ni prometer una transformación total.","ayuda":"Primera versión, contraste con el modelo y revisión propia."},{"tipo":"texto","texto":"<details><summary>Consultar modelo y retroalimentación</summary><p>Modelo: «Prepara una presentación de tres minutos con una guía y práctica» permite anticipar una actividad. No necesita afirmar que quien aún no sabe hacerlo vale menos.</p><p>Compara tu respuesta: identifica una condición explícita, una afirmación que necesita respaldo y una mejora concreta. El modelo es una posibilidad, no la única respuesta válida.</p></details>"}],"minutosEstimados":45},{"id":"pe-m07-l4","titulo":"Casos, testimonios y consentimiento","objetivo":"Aplicar casos, testimonios y consentimiento mediante un caso, una decisión comentada y una producción propia.","bloques":[{"tipo":"texto","texto":"<p>Antes de compartir una experiencia de otra persona, revisa si tienes permiso para ese uso concreto. Autorizar una entrevista no necesariamente autoriza publicidad, fotografía o publicación de datos personales. El alcance importa.</p><p>Puedes proteger privacidad usando casos compuestos o ficticios, siempre que lo indiques. No añadas una etiqueta de anonimato a una historia que todavía permite identificar a alguien por su puesto, fecha y detalles únicos. Comparte sólo lo necesario para enseñar.</p><p>Conserva el significado de los testimonios. Recortar una frase hasta convertir una opinión moderada en elogio absoluto puede distorsionarla. No fabriques reseñas ni nombres de clientes. Si no tienes un testimonio autorizado, usa una demostración propia o un ejemplo ficticio. El valor educativo no depende de hacer pasar ficción por prueba comercial.</p>"},{"tipo":"destacado","texto":"Caso ficticio: una participante permite usar su comentario en una evaluación interna, pero no habló de publicidad."},{"tipo":"practica","rotulo":"Decide y contrasta","preguntas":[{"p":"¿Qué corresponde antes de publicarlo?","ops":["Solicitar autorización para ese uso o elegir un ejemplo que no use su testimonio.","Publicarlo porque ya lo escribió alguna vez.","Cambiar sólo el nombre aunque los detalles la identifiquen."],"correcta":0,"explica":"El permiso debe corresponder al uso. Cambiar un nombre no elimina necesariamente la posibilidad de identificación.","pista":"Revisa la restricción del caso y el efecto de tu respuesta sobre la decisión de la otra persona."}]},{"tipo":"completar","rotulo":"Recupera la idea clave","items":[{"frase":"El permiso debe corresponder al ___ concreto de la información.","resp":["uso"],"explica":"Relaciona este concepto con la decisión que acabas de analizar."}]},{"tipo":"reflexion","rotulo":"Práctica aplicada · 20 minutos orientativos","pregunta":"Diseña una ficha de autorización necesaria para un testimonio ficticio: canal, contenido, identidad visible y alcance. No recolectes datos reales en esta práctica.","ayuda":"Primera versión, contraste con el modelo y revisión propia."},{"tipo":"texto","texto":"<details><summary>Consultar modelo y retroalimentación</summary><p>Modelo: distinguir una cita en un informe privado de una publicación comercial. La ficha sirve para identificar preguntas pendientes; no sustituye los procedimientos legales de la organización.</p><p>Compara tu respuesta: identifica una condición explícita, una afirmación que necesita respaldo y una mejora concreta. El modelo es una posibilidad, no la única respuesta válida.</p></details>"},{"tipo":"texto","texto":"<h3>Reto del módulo · 90 minutos orientativos</h3><p>Escribe una historia de 300 palabras que ilustre una decisión y acompáñala de evidencia independiente, límites y una alternativa. Identifica claramente que es ficticia.</p><p><strong>Entregable:</strong> Historia, comentario crítico y versión de 60 segundos.</p><p>Diagnóstico 15 min; primera versión 30; contraste 20; revisión 15; reflexión 10.</p>"},{"tipo":"reflexion","rotulo":"Bitácora del reto","pregunta":"Registra tu primera versión, una condición que faltaba y tu revisión justificada."},{"tipo":"texto","texto":"<h3>Autoevaluación del reto</h3><p>Revisa decisión clara, evidencia pertinente, condiciones explícitas y respeto al rechazo. En cada criterio: 0 ausente; 1 genérico; 2 concreto y justificado. Corrige los criterios con 0. Usa los modelos de las cuatro lecciones para contrastar tus decisiones.</p>"}],"minutosEstimados":45}],"quiz":{"titulo":"Evaluación de aplicación","preguntas":[{"p":"Una historia de éxito pertenece a una sola persona. ¿Qué puede aportar?","ops":["Un ejemplo ilustrativo con límites explícitos.","Prueba de que todos lograrán igual resultado.","Una estimación automática de eficacia."],"correcta":0,"explica":"Un relato muestra una experiencia; no determina representatividad."},{"p":"¿Qué elemento convierte una secuencia de hechos en una historia comprensible?","ops":["Sólo adjetivos emocionantes.","Una lista de características sin contexto.","Una situación, una tensión y una resolución relacionada."],"correcta":2,"explica":"La relación entre situación, decisión y consecuencia organiza el relato."},{"p":"Quieres usar la experiencia de un cliente identificable. ¿Qué necesitas revisar?","ops":["Que cambiar el título elimina toda consideración de privacidad.","Permiso para ese uso y los datos que realmente hacen falta.","Sólo que el relato sea favorable."],"correcta":1,"explica":"La identificación y el uso previsto requieren una revisión específica."},{"p":"Un caso didáctico combina varias situaciones inventadas. ¿Cómo presentarlo?","ops":["Como caso ficticio creado para aprender.","Como testimonio real de un alumno.","Como resultado científico."],"correcta":0,"explica":"Etiquetarlo evita confundir una ilustración con evidencia real."},{"p":"¿Qué emoción puede acompañar una propuesta responsable?","ops":["Miedo exagerado para impedir reflexión.","Culpa por no comprar.","Interés vinculado a consecuencias reales y opciones claras."],"correcta":2,"explica":"La emoción puede facilitar conexión sin distorsionar riesgos ni quitar autonomía."},{"p":"Un relato omite ayuda externa decisiva para atribuir todo a un curso. ¿Qué corregirías?","ops":["Mantenerlo porque es inspirador.","Incluir factores relevantes y moderar la atribución.","Añadir música más convincente."],"correcta":1,"explica":"La omisión altera la interpretación causal del resultado."},{"p":"¿Cuál cierre favorece reflexión?","ops":["Explicar qué ilustra el caso y qué no demuestra.","Asegurar que el mismo final espera a todos.","Pedir pago antes de presentar condiciones."],"correcta":0,"explica":"Un cierre responsable conserva el alcance del ejemplo."},{"p":"Una historia conmueve pero no apoya la afirmación del anuncio. ¿Qué harías?","ops":["Usarla como prueba porque genera emoción.","Aumentar su dramatismo.","Separar la ilustración de la evidencia necesaria."],"correcta":2,"explica":"La intensidad emocional no reemplaza la pertinencia probatoria."},{"p":"¿Cómo seleccionar detalles de una historia?","ops":["Inventar cifras y atribuirlas al protagonista.","Conservar los que explican la decisión sin exponer información innecesaria.","Publicar todo para que parezca auténtica."],"correcta":1,"explica":"Los detalles deben servir al aprendizaje y respetar el alcance del caso."},{"p":"Un participante no desea compartir una experiencia íntima. ¿Qué alternativa darías?","ops":["Resolver un caso ficticio equivalente.","Exigir exposición personal para demostrar compromiso.","Reducir su valoración por guardar privacidad."],"correcta":0,"explica":"El objetivo de práctica puede alcanzarse sin exigir revelaciones personales."}]}},{"id":"pe-m08","titulo":"Conversaciones y objeciones","resumen":"Resuelve una simulación con cinco objeciones: costo, tiempo, evidencia, experiencia previa y negativa final. Explica cuándo adaptar, cuándo investigar y cuándo cerrar.","lecciones":[{"id":"pe-m08-l1","titulo":"Explorar antes de responder","objetivo":"Aplicar explorar antes de responder mediante un caso, una decisión comentada y una producción propia.","bloques":[{"tipo":"imagen","url":"recursos/diplomado-persuasion-etica/visuales/pe-m08.svg","pie":"Mapa del módulo: Explorar antes de responder; Validar sin conceder automáticamente; Costo, tiempo y confianza; Aceptar un no y cerrar con respeto"},{"tipo":"texto","texto":"<p>Una objeción puede expresar falta de información, incompatibilidad o una decisión tomada. No asumas que toda frase es una barrera que debes vencer. «Es caro» puede significar presupuesto insuficiente, comparación con otra oferta o valor poco claro.</p><p>Pregunta con permiso y sin exigir justificación: «¿te serviría revisar qué incluye y compararlo con tu alternativa?». Si la persona no quiere seguir, respeta la respuesta. Cuando sí quiere, explora una incertidumbre cada vez y confirma lo entendido.</p><p>No respondas automáticamente con descuento. Podría reducir precio sin resolver horario, calidad o alcance. Distingue lo que puedes ajustar de lo que forma parte esencial del servicio. Una buena exploración también puede concluir que debes recomendar otra opción o no continuar la conversación.</p>"},{"tipo":"tarjetas","rotulo":"Guía activa del módulo · anticipa, compara y repasa","voz":false,"tarjetas":[{"frente":"¿Cómo aplicarías «Explorar antes de responder»? Piensa en una acción concreta antes de voltear.","reverso":"Modelo: puede faltar evidencia, no encajar el formato o no ser prioridad. «¿Qué aspecto necesitas aclarar, si quieres que lo revisemos?» permite que la respuesta cambie el siguiente paso.","ej":"Al terminar el módulo, vuelve a esta tarjeta y formula tu propio ejemplo."},{"frente":"¿Cómo aplicarías «Validar sin conceder automáticamente»? Piensa en una acción concreta antes de voltear.","reverso":"Modelo: «No ofrecemos revisión individual de trabajos. Hay rúbricas y ejemplos resueltos; si necesitas un tutor, este formato puede no ser suficiente». La claridad permite elegir.","ej":"Al terminar el módulo, vuelve a esta tarjeta y formula tu propio ejemplo."},{"frente":"¿Cómo aplicarías «Costo, tiempo y confianza»? Piensa en una acción concreta antes de voltear.","reverso":"Modelo: para confianza, ofrecer una lección de muestra; para tiempo, explicar estudio y prácticas; para costo, mostrar el precio total aprobado. No anuncies devolución, tutoría o financiamiento no confirmado.","ej":"Al terminar el módulo, vuelve a esta tarjeta y formula tu propio ejemplo."},{"frente":"¿Cómo aplicarías «Aceptar un no y cerrar con respeto»? Piensa en una acción concreta antes de voltear.","reverso":"Modelo: «Gracias por avisar; no continuaré enviando ofertas». Para seguimiento: «Te escribiré una vez el próximo mes sobre la nueva fecha que pediste». Los compromisos deben poder cumplirse en los sistemas usados.","ej":"Al terminar el módulo, vuelve a esta tarjeta y formula tu propio ejemplo."}]},{"tipo":"destacado","texto":"Caso ficticio: una persona dice «se me hace caro» después de recibir un temario."},{"tipo":"practica","rotulo":"Decide y contrasta","preguntas":[{"p":"¿Qué primer paso es razonable?","ops":["Bajar inmediatamente el precio sin conocer la dificultad.","Decir que quien lo considera caro no valora aprender.","Preguntar si desea revisar presupuesto, alcance o comparación con otra opción."],"correcta":2,"explica":"La primera respuesta abre información y permite no continuar. Descalificar no explica valor; descontar no identifica el problema.","pista":"Revisa la restricción del caso y el efecto de tu respuesta sobre la decisión de la otra persona."}]},{"tipo":"completar","rotulo":"Recupera la idea clave","items":[{"frase":"Antes de responder una objeción conviene ___ su significado.","resp":["explorar"],"explica":"Relaciona este concepto con la decisión que acabas de analizar."}]},{"tipo":"reflexion","rotulo":"Práctica aplicada · 20 minutos orientativos","pregunta":"Escribe tres significados posibles de «no me convence» y una pregunta neutral para distinguirlos. Evita convertir una hipótesis en diagnóstico.","ayuda":"Primera versión, contraste con el modelo y revisión propia."},{"tipo":"texto","texto":"<details><summary>Consultar modelo y retroalimentación</summary><p>Modelo: puede faltar evidencia, no encajar el formato o no ser prioridad. «¿Qué aspecto necesitas aclarar, si quieres que lo revisemos?» permite que la respuesta cambie el siguiente paso.</p><p>Compara tu respuesta: identifica una condición explícita, una afirmación que necesita respaldo y una mejora concreta. El modelo es una posibilidad, no la única respuesta válida.</p></details>"}],"minutosEstimados":45},{"id":"pe-m08-l2","titulo":"Validar sin conceder automáticamente","objetivo":"Aplicar validar sin conceder automáticamente mediante un caso, una decisión comentada y una producción propia.","bloques":[{"tipo":"texto","texto":"<p>Validar significa reconocer una experiencia o preocupación sin afirmar que toda interpretación sea correcta. «Entiendo que el retraso afecta tu planificación» reconoce un efecto. No obliga a aceptar que toda la organización sea incompetente.</p><p>Separa reconocimiento, hechos comprobados y acción posible. Evita usar «pero» como una forma de borrar lo anterior: puedes dividir las ideas en frases claras. Si discrepas, explica sobre qué dato o condición y ofrece revisar evidencia.</p><p>No imites emociones ni utilices empatía como una fórmula para acelerar una venta. La escucha se comprueba cuando la información cambia tu respuesta. Cuando no puedes satisfacer una petición, dilo con claridad y propone sólo alternativas reales. Una negativa respetuosa puede ser más útil que una aceptación ambigua que después incumplirás.</p>"},{"tipo":"destacado","texto":"Caso ficticio: alguien pide tutoría personal en un diplomado autogestivo."},{"tipo":"practica","rotulo":"Decide y contrasta","preguntas":[{"p":"¿Qué respuesta valida y aclara?","ops":["Decir que su necesidad de ayuda es el problema.","Entiendo que buscas acompañamiento; este programa no incluye tutoría individual y conviene valorar otro formato.","Decir que sí tendrá atención personalizada aunque sólo hay respuestas automáticas."],"correcta":1,"explica":"La respuesta reconoce la necesidad y mantiene el alcance real. Prometer tutoría inexistente crea expectativas incompatibles.","pista":"Revisa la restricción del caso y el efecto de tu respuesta sobre la decisión de la otra persona."}]},{"tipo":"completar","rotulo":"Recupera la idea clave","items":[{"frase":"Reconocer una preocupación no significa aceptar cualquier ___.","resp":["petición"],"explica":"Relaciona este concepto con la decisión que acabas de analizar."}]},{"tipo":"reflexion","rotulo":"Práctica aplicada · 20 minutos orientativos","pregunta":"Redacta una negativa respetuosa a una solicitud fuera de alcance. Incluye reconocimiento, límite y una alternativa real o la ausencia de ella.","ayuda":"Primera versión, contraste con el modelo y revisión propia."},{"tipo":"texto","texto":"<details><summary>Consultar modelo y retroalimentación</summary><p>Modelo: «No ofrecemos revisión individual de trabajos. Hay rúbricas y ejemplos resueltos; si necesitas un tutor, este formato puede no ser suficiente». La claridad permite elegir.</p><p>Compara tu respuesta: identifica una condición explícita, una afirmación que necesita respaldo y una mejora concreta. El modelo es una posibilidad, no la única respuesta válida.</p></details>"},{"tipo":"relacionar","rotulo":"Relaciona el concepto con su aplicación","voz":false,"pares":[["Explorar","¿Qué parte del costo te preocupa?"],["Validar","Entiendo que necesitas cuidar tu presupuesto"],["Responder","Desglosar el costo y ofrecer una alternativa viable"],["Cerrar con respeto","Aceptar que esta opción no encaja ahora"]]},{"tipo":"texto","texto":"<p><strong>Contrasta tu razonamiento:</strong> después de relacionar, explica por qué cada ejemplo corresponde a ese concepto y escribe un contraejemplo. No basta memorizar la pareja: identifica la conducta observable que la distingue.</p>"}],"minutosEstimados":45},{"id":"pe-m08-l3","titulo":"Costo, tiempo y confianza","objetivo":"Aplicar costo, tiempo y confianza mediante un caso, una decisión comentada y una producción propia.","bloques":[{"tipo":"texto","texto":"<p>Las objeciones requieren información distinta. Para costo, revisa monto total y opciones reales; para tiempo, carga y plazos; para confianza, evidencia, condiciones y experiencia. Responder a todas con entusiasmo evita el asunto central.</p><p>Usa una matriz: objeción expresada, dato que falta, respuesta disponible y límite. Si no tienes un dato, comprométete a comprobarlo sólo cuando puedas hacerlo. No inventes facilidades de pago, garantías o tiempos para cerrar.</p><p>Comprueba si la respuesta resolvió la pregunta sin forzar aceptación: «¿esto aclara el horario o queda otra condición?». Que una duda se aclare no significa que la persona quiera comprar. Distingue comprensión de acuerdo. Guarda consistencia entre lo dicho verbalmente y las condiciones escritas.</p>"},{"tipo":"destacado","texto":"Caso ficticio: alguien entiende el precio, pero no sabe si podrá estudiar tres horas por semana."},{"tipo":"practica","rotulo":"Decide y contrasta","preguntas":[{"p":"¿Qué información responde a su objeción?","ops":["Distribución de carga y ritmo flexible real, sin prometer una duración menor de trabajo.","Un testimonio de alguien que ganó más dinero.","Una frase que diga que todo es fácil y no requiere esfuerzo."],"correcta":0,"explica":"La objeción es de tiempo. Un resultado ajeno no reduce la carga ni demuestra que su agenda permita realizarla.","pista":"Revisa la restricción del caso y el efecto de tu respuesta sobre la decisión de la otra persona."}]},{"tipo":"completar","rotulo":"Recupera la idea clave","items":[{"frase":"La respuesta debe corresponder a la ___ expresada.","resp":["objeción"],"explica":"Relaciona este concepto con la decisión que acabas de analizar."}]},{"tipo":"reflexion","rotulo":"Práctica aplicada · 20 minutos orientativos","pregunta":"Construye una matriz de costo, tiempo y confianza para este diplomado. Usa sólo características documentadas; marca lo que aún debe confirmarse.","ayuda":"Primera versión, contraste con el modelo y revisión propia."},{"tipo":"texto","texto":"<details><summary>Consultar modelo y retroalimentación</summary><p>Modelo: para confianza, ofrecer una lección de muestra; para tiempo, explicar estudio y prácticas; para costo, mostrar el precio total aprobado. No anuncies devolución, tutoría o financiamiento no confirmado.</p><p>Compara tu respuesta: identifica una condición explícita, una afirmación que necesita respaldo y una mejora concreta. El modelo es una posibilidad, no la única respuesta válida.</p></details>"}],"minutosEstimados":45},{"id":"pe-m08-l4","titulo":"Aceptar un no y cerrar con respeto","objetivo":"Aplicar aceptar un no y cerrar con respeto mediante un caso, una decisión comentada y una producción propia.","bloques":[{"tipo":"texto","texto":"<p>Una negativa puede ser final. No necesitas convertirla en una oportunidad para otra técnica. Agradece la claridad, confirma si queda alguna gestión pendiente y evita insistir por otros canales para eludir la decisión.</p><p>Si la persona solicita seguimiento, acuerda motivo, canal y momento. «Escríbeme en un mes» no autoriza mensajes diarios. Si no existe autorización o interés, cerrar la conversación puede ser lo adecuado.</p><p>El cierre también protege la claridad del registro: una solicitud de información no es una inscripción y una conversación cordial no es consentimiento comercial ilimitado. Aprende del intercambio sin culpar al interlocutor. Puedes revisar si tu oferta encajaba y qué información faltó, pero no necesitas obtener una explicación personal de cada rechazo.</p>"},{"tipo":"destacado","texto":"Caso ficticio: «Gracias, ya decidí que no quiero recibir más ofertas»."},{"tipo":"practica","rotulo":"Decide y contrasta","preguntas":[{"p":"¿Qué corresponde?","ops":["Contactar por otra cuenta para intentarlo de nuevo.","Preguntar repetidamente hasta que explique una razón que aceptes.","Confirmar que respetarás esa preferencia y cerrar la conversación."],"correcta":2,"explica":"La preferencia es clara. Cambiar de canal o exigir explicaciones no respeta la decisión.","pista":"Revisa la restricción del caso y el efecto de tu respuesta sobre la decisión de la otra persona."}]},{"tipo":"completar","rotulo":"Recupera la idea clave","items":[{"frase":"Un seguimiento acordado debe respetar motivo, canal y ___.","resp":["momento"],"explica":"Relaciona este concepto con la decisión que acabas de analizar."}]},{"tipo":"reflexion","rotulo":"Práctica aplicada · 20 minutos orientativos","pregunta":"Escribe dos cierres: una negativa definitiva y un seguimiento solicitado para el mes siguiente. Indica qué permiso existe en cada caso.","ayuda":"Primera versión, contraste con el modelo y revisión propia."},{"tipo":"texto","texto":"<details><summary>Consultar modelo y retroalimentación</summary><p>Modelo: «Gracias por avisar; no continuaré enviando ofertas». Para seguimiento: «Te escribiré una vez el próximo mes sobre la nueva fecha que pediste». Los compromisos deben poder cumplirse en los sistemas usados.</p><p>Compara tu respuesta: identifica una condición explícita, una afirmación que necesita respaldo y una mejora concreta. El modelo es una posibilidad, no la única respuesta válida.</p></details>"},{"tipo":"texto","texto":"<h3>Reto del módulo · 90 minutos orientativos</h3><p>Resuelve una simulación con cinco objeciones: costo, tiempo, evidencia, experiencia previa y negativa final. Explica cuándo adaptar, cuándo investigar y cuándo cerrar.</p><p><strong>Entregable:</strong> Diálogo de diez turnos con notas de decisión.</p><p>Diagnóstico 15 min; primera versión 30; contraste 20; revisión 15; reflexión 10.</p>"},{"tipo":"reflexion","rotulo":"Bitácora del reto","pregunta":"Registra tu primera versión, una condición que faltaba y tu revisión justificada."},{"tipo":"texto","texto":"<h3>Autoevaluación del reto</h3><p>Revisa decisión clara, evidencia pertinente, condiciones explícitas y respeto al rechazo. En cada criterio: 0 ausente; 1 genérico; 2 concreto y justificado. Corrige los criterios con 0. Usa los modelos de las cuatro lecciones para contrastar tus decisiones.</p>"}],"minutosEstimados":45}],"quiz":{"titulo":"Evaluación de aplicación","preguntas":[{"p":"Una persona dice es demasiado caro. ¿Qué conviene explorar?","ops":["Cómo hacerla sentir culpable por el precio.","Qué descuento ofrecer sin entender el problema.","Con qué presupuesto o alternativa compara la propuesta."],"correcta":2,"explica":"La objeción puede referirse a presupuesto, valor o comparación; no se debe adivinar."},{"p":"¿Qué significa validar una preocupación?","ops":["Admitir que tu propuesta es inútil.","Reconocer que merece atención sin aceptar automáticamente su conclusión.","Conceder siempre lo solicitado."],"correcta":1,"explica":"Reconocimiento y acuerdo son acciones diferentes."},{"p":"El interlocutor dice que no tiene tiempo. ¿Qué respuesta ayuda?","ops":["Preguntar qué dedicación sería viable y explicar la exigencia real.","Decir que todos tienen las mismas horas.","Prometer que no requiere esfuerzo aunque sí lo requiera."],"correcta":0,"explica":"Una restricción necesita examinarse, no descalificarse ni ocultarse."},{"p":"Tras recibir información suficiente, la persona dice no. ¿Qué haces?","ops":["Insistir por varios canales hasta que responda sí.","Interpretar que su no siempre significa tal vez.","Respetar la decisión y cerrar de forma clara."],"correcta":2,"explica":"Aceptar el rechazo es parte de una interacción voluntaria."},{"p":"Un cliente plantea dos problemas distintos. ¿Qué conviene hacer?","ops":["Suponer que ambos son excusas.","Separarlos, confirmar prioridad y responder cada uno.","Responder al más fácil e ignorar el otro."],"correcta":1,"explica":"Separar problemas evita respuestas incompletas."},{"p":"¿Qué respuesta aborda una duda sobre confianza?","ops":["Ofrecer información verificable y reconocer límites.","Exigir confianza como prueba de lealtad.","Usar urgencia para impedir preguntas."],"correcta":0,"explica":"La confianza se apoya en información y conducta, no en exigir aceptación."},{"p":"No puedes satisfacer una condición esencial. ¿Qué es razonable?","ops":["Prometerla para cerrar y resolver después.","Describir al cliente como difícil.","Reconocer la incompatibilidad y explorar alternativas reales."],"correcta":2,"explica":"Una incompatibilidad puede justificar no contratar."},{"p":"¿Cuándo conviene una pausa?","ops":["Nunca, porque toda pausa pierde poder.","Cuando falta información o la conversación requiere recuperar claridad.","Sólo cuando una parte ya aceptó."],"correcta":1,"explica":"Una pausa puede mejorar la calidad de la decisión."},{"p":"Un desacuerdo se vuelve personal. ¿Qué frase ayuda?","ops":["Volvamos al plazo y a los recursos que necesitamos acordar.","Siempre eres imposible.","Si discrepas no entiendes nada."],"correcta":0,"explica":"Centrarse en el problema reduce ataques y permite avanzar."},{"p":"¿Qué seguimiento es respetuoso?","ops":["Enviar mensajes diarios sin respuesta.","Cambiar de número si bloquea el contacto.","Acordar canal y fecha si la persona desea retomarlo."],"correcta":2,"explica":"El seguimiento necesita respetar preferencias y límites expresados."}]}},{"id":"pe-m09","titulo":"Voz, presencia y canales digitales","resumen":"Adapta una propuesta a correo, mensaje breve y exposición de tres minutos. Comprueba legibilidad, condiciones y comprensión, usando grabación privada sólo si lo deseas.","lecciones":[{"id":"pe-m09-l1","titulo":"Voz, ritmo y pausas","objetivo":"Aplicar voz, ritmo y pausas mediante un caso, una decisión comentada y una producción propia.","bloques":[{"tipo":"imagen","url":"recursos/diplomado-persuasion-etica/visuales/pe-m09.svg","pie":"Mapa del módulo: Voz, ritmo y pausas; Comunicación no verbal contextual; Correo y mensajería; Presentaciones accesibles"},{"tipo":"texto","texto":"<p>La voz puede facilitar o dificultar que se siga una idea. Hablar muy rápido reduce oportunidades de procesar; una pausa puede separar conceptos o permitir una pregunta. No existe una velocidad ideal para todas las personas y situaciones.</p><p>Ensaya con una intención por párrafo. Marca dónde presentarás una idea, un ejemplo y una condición importante. No aceleres al mencionar costos o límites. Revisa volumen y audibilidad sin convertir una voz grave o una forma de hablar en prueba de autoridad.</p><p>Puedes grabarte de forma privada o leer a otra persona que acepte escuchar. Pide retroalimentación específica: qué se entendió, dónde se perdió el hilo y qué faltó. No evalúes sólo si tu voz «suena segura». Una presentación accesible puede necesitar texto, subtítulos, pausas o un canal alternativo.</p>"},{"tipo":"tarjetas","rotulo":"Guía activa del módulo · anticipa, compara y repasa","voz":false,"tarjetas":[{"frente":"¿Cómo aplicarías «Voz, ritmo y pausas»? Piensa en una acción concreta antes de voltear.","reverso":"Modelo: una pausa antes del precio permite identificarlo; otra después permite preguntar. No necesitas imitar una voz ajena ni subir volumen para parecer convincente.","ej":"Al terminar el módulo, vuelve a esta tarjeta y formula tu propio ejemplo."},{"frente":"¿Cómo aplicarías «Comunicación no verbal contextual»? Piensa en una acción concreta antes de voltear.","reverso":"Modelo: un silencio puede ser reflexión, conexión inestable o desacuerdo. «¿Quieres tiempo para revisarlo o prefieres que aclare algo?» ofrece opciones sin afirmar que conoces la causa.","ej":"Al terminar el módulo, vuelve a esta tarjeta y formula tu propio ejemplo."},{"frente":"¿Cómo aplicarías «Correo y mensajería»? Piensa en una acción concreta antes de voltear.","reverso":"Modelo: «Te comparto el temario que solicitaste. Es autogestivo y no incluye tutoría individual. ¿Quieres aclarar alguna parte antes de decidir?». Verifica que el enlace y las condiciones correspondan al programa real.","ej":"Al terminar el módulo, vuelve a esta tarjeta y formula tu propio ejemplo."},{"frente":"¿Cómo aplicarías «Presentaciones accesibles»? Piensa en una acción concreta antes de voltear.","reverso":"Modelo: «Solicitudes completadas por semana, semanas 1–4» es más claro que «Éxito». El texto debe explicar qué se midió y no convertir una tendencia visual en prueba causal.","ej":"Al terminar el módulo, vuelve a esta tarjeta y formula tu propio ejemplo."}]},{"tipo":"destacado","texto":"Caso ficticio: explicas lentamente beneficios y muy rápido las condiciones de pago."},{"tipo":"practica","rotulo":"Decide y contrasta","preguntas":[{"p":"¿Qué deberías ajustar?","ops":["Bajar aún más el volumen al hablar de costos.","Dar a las condiciones tiempo y claridad equivalentes a su importancia.","Mantener el ritmo porque así nadie interrumpe."],"correcta":1,"explica":"Las condiciones forman parte de la decisión. La voz no debe usarse para volverlas menos perceptibles.","pista":"Revisa la restricción del caso y el efecto de tu respuesta sobre la decisión de la otra persona."}]},{"tipo":"completar","rotulo":"Recupera la idea clave","items":[{"frase":"Una ___ puede separar ideas y permitir comprensión.","resp":["pausa"],"explica":"Relaciona este concepto con la decisión que acabas de analizar."}]},{"tipo":"reflexion","rotulo":"Práctica aplicada · 20 minutos orientativos","pregunta":"Marca pausas en un guion de 180 palabras y ensaya dos versiones. Anota qué parte se entiende mejor y qué condición merece más claridad.","ayuda":"Primera versión, contraste con el modelo y revisión propia."},{"tipo":"texto","texto":"<details><summary>Consultar modelo y retroalimentación</summary><p>Modelo: una pausa antes del precio permite identificarlo; otra después permite preguntar. No necesitas imitar una voz ajena ni subir volumen para parecer convincente.</p><p>Compara tu respuesta: identifica una condición explícita, una afirmación que necesita respaldo y una mejora concreta. El modelo es una posibilidad, no la única respuesta válida.</p></details>"}],"minutosEstimados":45},{"id":"pe-m09-l2","titulo":"Comunicación no verbal contextual","objetivo":"Aplicar comunicación no verbal contextual mediante un caso, una decisión comentada y una producción propia.","bloques":[{"tipo":"texto","texto":"<p>Postura, distancia, mirada y gestos pueden influir en una interacción, pero no permiten leer pensamientos con certeza. Cruzar brazos puede expresar comodidad, frío o múltiples situaciones. Un gesto aislado no demuestra mentira, rechazo ni atracción.</p><p>Observa el contexto y evita generalizaciones sobre cultura, discapacidad o personalidad. Adapta tu conducta para facilitar comodidad: espacio suficiente, cámara opcional cuando proceda y ausencia de contacto físico no solicitado. No fuerces mirada constante como medida universal de atención.</p><p>Si notas una dificultad, compruébala con una pregunta respetuosa: «¿se escucha bien?» o «¿prefieres que lo revisemos por escrito?». Para mejorar presencia, trabaja sobre acciones que controlas, como no bloquear una salida o no interrumpir, en lugar de intentar descifrar estados internos a partir de señales ambiguas.</p>"},{"tipo":"destacado","texto":"Caso ficticio: una persona evita mirar a cámara durante una explicación."},{"tipo":"practica","rotulo":"Decide y contrasta","preguntas":[{"p":"¿Qué interpretación es responsable?","ops":["La señal es ambigua; puedo preguntar por comodidad o comprensión sin atribuir intención.","Está mintiendo necesariamente.","Debo obligarla a mirar para saber si presta atención."],"correcta":0,"explica":"El contexto ofrece varias explicaciones. No se puede diagnosticar intención a partir de una sola conducta.","pista":"Revisa la restricción del caso y el efecto de tu respuesta sobre la decisión de la otra persona."}]},{"tipo":"completar","rotulo":"Recupera la idea clave","items":[{"frase":"Un gesto aislado necesita ___ para interpretarse con prudencia.","resp":["contexto"],"explica":"Relaciona este concepto con la decisión que acabas de analizar."}]},{"tipo":"reflexion","rotulo":"Práctica aplicada · 20 minutos orientativos","pregunta":"Anota tres señales no verbales y tres explicaciones posibles para cada una. Redacta una pregunta que ayude sin invadir privacidad.","ayuda":"Primera versión, contraste con el modelo y revisión propia."},{"tipo":"texto","texto":"<details><summary>Consultar modelo y retroalimentación</summary><p>Modelo: un silencio puede ser reflexión, conexión inestable o desacuerdo. «¿Quieres tiempo para revisarlo o prefieres que aclare algo?» ofrece opciones sin afirmar que conoces la causa.</p><p>Compara tu respuesta: identifica una condición explícita, una afirmación que necesita respaldo y una mejora concreta. El modelo es una posibilidad, no la única respuesta válida.</p></details>"},{"tipo":"relacionar","rotulo":"Relaciona el concepto con su aplicación","voz":false,"pares":[["Pausa","Dar tiempo para comprender una cifra"],["Accesibilidad","Compartir una versión escrita legible"],["Señal ambigua","Los brazos cruzados admiten varias explicaciones"],["Comprobación","Pedir que expliquen con sus palabras el siguiente paso"]]},{"tipo":"texto","texto":"<p><strong>Contrasta tu razonamiento:</strong> después de relacionar, explica por qué cada ejemplo corresponde a ese concepto y escribe un contraejemplo. No basta memorizar la pareja: identifica la conducta observable que la distingue.</p>"}],"minutosEstimados":45},{"id":"pe-m09-l3","titulo":"Correo y mensajería","objetivo":"Aplicar correo y mensajería mediante un caso, una decisión comentada y una producción propia.","bloques":[{"tipo":"texto","texto":"<p>Un mensaje digital pierde parte del contexto de una conversación. Especifica asunto, propósito, datos necesarios y respuesta solicitada. Evita enviar varios mensajes que obliguen a reconstruir la propuesta o interpretar urgencia a partir de signos de exclamación.</p><p>Adapta longitud al canal sin ocultar condiciones. Un mensaje breve puede enlazar a un temario, pero debe aclarar si el siguiente paso es informativo o implica un pago. Comprueba enlaces, remitente y destino de respuestas antes de utilizar una plantilla.</p><p>No confundas acceso a un número con permiso para enviar cualquier comunicación. Respeta preferencias de contacto y no envíes datos privados de terceros en grupos. Una falta de respuesta no confirma aceptación. Si existe seguimiento acordado, mantén el motivo y el plazo; si no, evita encadenar insistencias.</p>"},{"tipo":"destacado","texto":"Caso ficticio: mandas «¿te interesa?» sin contexto a una persona que pidió información de un programa concreto."},{"tipo":"practica","rotulo":"Decide y contrasta","preguntas":[{"p":"¿Qué versión facilita responder?","ops":["Enviar cinco mensajes de urgencia separados.","Dar por inscrita a la persona si no responde.","Identificar el programa, resumir lo solicitado y preguntar qué dato necesita aclarar."],"correcta":2,"explica":"El contexto reduce ambigüedad y permite una respuesta pertinente. Silencio no equivale a inscripción.","pista":"Revisa la restricción del caso y el efecto de tu respuesta sobre la decisión de la otra persona."}]},{"tipo":"completar","rotulo":"Recupera la idea clave","items":[{"frase":"La falta de respuesta no significa ___.","resp":["aceptación"],"explica":"Relaciona este concepto con la decisión que acabas de analizar."}]},{"tipo":"reflexion","rotulo":"Práctica aplicada · 20 minutos orientativos","pregunta":"Redacta un correo con asunto y una versión breve para mensajería. Incluye una única solicitud clara y un enlace descriptivo ficticio.","ayuda":"Primera versión, contraste con el modelo y revisión propia."},{"tipo":"texto","texto":"<details><summary>Consultar modelo y retroalimentación</summary><p>Modelo: «Te comparto el temario que solicitaste. Es autogestivo y no incluye tutoría individual. ¿Quieres aclarar alguna parte antes de decidir?». Verifica que el enlace y las condiciones correspondan al programa real.</p><p>Compara tu respuesta: identifica una condición explícita, una afirmación que necesita respaldo y una mejora concreta. El modelo es una posibilidad, no la única respuesta válida.</p></details>"}],"minutosEstimados":45},{"id":"pe-m09-l4","titulo":"Presentaciones accesibles","objetivo":"Aplicar presentaciones accesibles mediante un caso, una decisión comentada y una producción propia.","bloques":[{"tipo":"texto","texto":"<p>Una presentación debe permitir comprender la propuesta sin depender de un único canal. Una gráfica necesita títulos y unidades; una imagen informativa necesita explicación; un video necesita alternativa textual cuando no se puede reproducir o escuchar.</p><p>Utiliza contraste legible, tamaño de letra suficiente y una idea principal por sección. No codifiques toda una decisión únicamente con rojo y verde: añade etiquetas. Explica qué debe observarse en una visualización antes de interpretarla.</p><p>Prepara una versión que funcione sin conexión o sin audio. Ensaya desde el dispositivo que usará la audiencia, especialmente móvil. Si reduces contenido para que quepa, comprueba que no desaparezcan límites relevantes. La accesibilidad no es una decoración final: forma parte de que otras personas puedan examinar la propuesta y participar.</p>"},{"tipo":"destacado","texto":"Caso ficticio: una gráfica presenta dos opciones sólo mediante colores sin etiquetas."},{"tipo":"practica","rotulo":"Decide y contrasta","preguntas":[{"p":"¿Qué mejora es necesaria?","ops":["Eliminar los datos y pedir que confíen en el presentador.","Añadir etiquetas y una explicación textual de la comparación.","Usar colores más brillantes sin cambiar nada más."],"correcta":1,"explica":"Las etiquetas y el texto permiten interpretar la comparación aunque el color no sea distinguible.","pista":"Revisa la restricción del caso y el efecto de tu respuesta sobre la decisión de la otra persona."}]},{"tipo":"completar","rotulo":"Recupera la idea clave","items":[{"frase":"Un recurso audiovisual debe tener una alternativa ___ cuando sea necesaria.","resp":["textual"],"explica":"Relaciona este concepto con la decisión que acabas de analizar."}]},{"tipo":"reflexion","rotulo":"Práctica aplicada · 20 minutos orientativos","pregunta":"Diseña una diapositiva textual y describe una gráfica con título, unidades, periodo y conclusión limitada. Revisa si se entiende sin color.","ayuda":"Primera versión, contraste con el modelo y revisión propia."},{"tipo":"texto","texto":"<details><summary>Consultar modelo y retroalimentación</summary><p>Modelo: «Solicitudes completadas por semana, semanas 1–4» es más claro que «Éxito». El texto debe explicar qué se midió y no convertir una tendencia visual en prueba causal.</p><p>Compara tu respuesta: identifica una condición explícita, una afirmación que necesita respaldo y una mejora concreta. El modelo es una posibilidad, no la única respuesta válida.</p></details>"},{"tipo":"texto","texto":"<h3>Reto del módulo · 90 minutos orientativos</h3><p>Adapta una propuesta a correo, mensaje breve y exposición de tres minutos. Comprueba legibilidad, condiciones y comprensión, usando grabación privada sólo si lo deseas.</p><p><strong>Entregable:</strong> Tres versiones y registro de mejoras después del ensayo.</p><p>Diagnóstico 15 min; primera versión 30; contraste 20; revisión 15; reflexión 10.</p>"},{"tipo":"reflexion","rotulo":"Bitácora del reto","pregunta":"Registra tu primera versión, una condición que faltaba y tu revisión justificada."},{"tipo":"texto","texto":"<h3>Autoevaluación del reto</h3><p>Revisa decisión clara, evidencia pertinente, condiciones explícitas y respeto al rechazo. En cada criterio: 0 ausente; 1 genérico; 2 concreto y justificado. Corrige los criterios con 0. Usa los modelos de las cuatro lecciones para contrastar tus decisiones.</p>"}],"minutosEstimados":45}],"quiz":{"titulo":"Evaluación de aplicación","preguntas":[{"p":"Alguien evita mirar a los ojos. ¿Qué puedes concluir?","ops":["Que no está interesado en nada.","Que necesitas contexto; una señal aislada no demuestra engaño.","Que miente con seguridad."],"correcta":1,"explica":"Las señales no verbales admiten múltiples explicaciones."},{"p":"¿Qué función puede cumplir una pausa al hablar?","ops":["Separar ideas y dar tiempo para comprender.","Garantizar obediencia.","Sustituir la evidencia del mensaje."],"correcta":0,"explica":"La pausa organiza la exposición, no demuestra veracidad."},{"p":"¿Cómo adaptar un mensaje de voz para accesibilidad?","ops":["Repetirlo más fuerte como única alternativa.","Omitir fechas y condiciones del texto.","Ofrecer también texto con la información esencial."],"correcta":2,"explica":"El texto permite acceder al contenido sin depender de la escucha."},{"p":"Un correo contiene cinco solicitudes sin orden. ¿Qué ajuste ayuda?","ops":["Añadir urgencia a cada oración.","Priorizar, numerar acciones y aclarar plazos.","Escribir todo en mayúsculas."],"correcta":1,"explica":"Una organización visible facilita responder correctamente."},{"p":"¿Qué evaluación de una presentación es útil?","ops":["Comprobar audibilidad, ritmo y comprensión de ideas.","Calificar personalidad por un solo gesto.","Suponer que hablar rápido significa dominar el tema."],"correcta":0,"explica":"Los criterios observables permiten mejorar sin diagnosticar a la persona."},{"p":"Un video incluye una gráfica difícil de ver. ¿Qué recurso ayuda?","ops":["Dar por hecho que todos la ven igual.","Añadir música.","Describir verbalmente sus datos esenciales y ofrecer alternativa textual."],"correcta":2,"explica":"La información visual esencial necesita una vía alternativa accesible."},{"p":"¿Cuál asunto de correo informa mejor?","ops":["Hola.","Confirmar horario de reunión del jueves.","URGENTE IMPERDIBLE."],"correcta":1,"explica":"El asunto concreto permite anticipar tema y acción."},{"p":"¿Qué harías antes de enviar una nota de voz larga?","ops":["Valorar si el canal es adecuado y ofrecer un resumen escrito.","Suponer que todos prefieren escuchar.","Eliminar cualquier resumen para que escuchen todo."],"correcta":0,"explica":"El canal debe responder al contexto y posibilidades del receptor."},{"p":"Un gesto cambia durante una conversación tensa. ¿Qué respuesta es prudente?","ops":["Afirmar que sabes exactamente qué siente.","Usarlo como prueba de culpabilidad.","Preguntar si conviene aclarar algo o hacer una pausa."],"correcta":2,"explica":"Una pregunta contextual evita atribuciones infundadas."},{"p":"¿Qué mejora una práctica de exposición grabada?","ops":["Imitar todos los gestos de una persona famosa.","Revisar un objetivo concreto por intento y comparar cambios.","Buscar una presencia perfecta antes de empezar."],"correcta":1,"explica":"La práctica focalizada produce retroalimentación accionable."}]}},{"id":"pe-m10","titulo":"Laboratorio integrador y transferencia","resumen":"Audita una propuesta completa ajena o ficticia con la rúbrica antes de evaluar la tuya. Entrega una versión corregida y una explicación de qué evidencia todavía falta.","lecciones":[{"id":"pe-m10-l1","titulo":"Preparar una intervención","objetivo":"Aplicar preparar una intervención mediante un caso, una decisión comentada y una producción propia.","bloques":[{"tipo":"imagen","url":"recursos/diplomado-persuasion-etica/visuales/pe-m10.svg","pie":"Mapa del módulo: Preparar una intervención; Simular preguntas difíciles; Medir resultados sin exagerar; Revisar, transferir y cerrar el proyecto"},{"tipo":"texto","texto":"<p>Preparar una conversación comienza antes del guion. Define qué decisión está en juego, quién participa, qué información está confirmada y qué límites no puedes cambiar. Establece también cuándo no conviene continuar.</p><p>Usa una hoja de preparación: objetivo, intereses conocidos, hipótesis, evidencia, alternativas y preguntas. Distingue resultado deseado de resultado aceptable. Si sólo aceptas un sí, puedes ignorar información que muestra falta de encaje.</p><p>Ensaya una apertura breve y una explicación ampliada. Anticipa preguntas, pero no memorices respuestas para cualquier situación. Reserva espacio para escuchar. Un plan útil es modificable: cuando aparece una restricción nueva, revisa alcance, plazo o alternativa. Documenta compromisos para que la conversación no dependa de recuerdos distintos.</p>"},{"tipo":"tarjetas","rotulo":"Guía activa del módulo · anticipa, compara y repasa","voz":false,"tarjetas":[{"frente":"¿Cómo aplicarías «Preparar una intervención»? Piensa en una acción concreta antes de voltear.","reverso":"Modelo: no recomendar un curso autogestivo si la necesidad principal es supervisión individual continua. Tener una condición de no encaje evita convertir toda conversación en una venta forzada.","ej":"Al terminar el módulo, vuelve a esta tarjeta y formula tu propio ejemplo."},{"frente":"¿Cómo aplicarías «Simular preguntas difíciles»? Piensa en una acción concreta antes de voltear.","reverso":"Modelo: «No contamos con seguimiento de ventas. Sí evaluamos resolución de casos al terminar cada módulo». Esa respuesta diferencia el aprendizaje evaluado de un resultado laboral no medido.","ej":"Al terminar el módulo, vuelve a esta tarjeta y formula tu propio ejemplo."},{"frente":"¿Cómo aplicarías «Medir resultados sin exagerar»? Piensa en una acción concreta antes de voltear.","reverso":"Modelo: medir si cinco lectores ficticios identifican costo, alcance y siguiente paso en una propuesta. Esto evalúa claridad del mensaje, no ventas ni cambios duraderos de conducta.","ej":"Al terminar el módulo, vuelve a esta tarjeta y formula tu propio ejemplo."},{"frente":"¿Cómo aplicarías «Revisar, transferir y cerrar el proyecto»? Piensa en una acción concreta antes de voltear.","reverso":"Modelo: cambiar una garantía por un resultado observable, añadir costo total y preparar una respuesta que acepte un no. Explica qué información provocó cada cambio y qué incertidumbre permanece.","ej":"Al terminar el módulo, vuelve a esta tarjeta y formula tu propio ejemplo."}]},{"tipo":"destacado","texto":"Caso ficticio: presentarás una propuesta a una organización, pero desconoces quién puede autorizar el presupuesto."},{"tipo":"practica","rotulo":"Decide y contrasta","preguntas":[{"p":"¿Qué debe resolverse antes de cerrar?","ops":["Cómo se toma la decisión y qué revisión de presupuesto hace falta.","Conseguir un sí de cualquier asistente y tratarlo como autorización.","Omitir precio para que nadie retrase la decisión."],"correcta":0,"explica":"La aceptación de una persona sin atribuciones puede no ser un acuerdo válido para la organización. El proceso de decisión importa.","pista":"Revisa la restricción del caso y el efecto de tu respuesta sobre la decisión de la otra persona."}]},{"tipo":"completar","rotulo":"Recupera la idea clave","items":[{"frase":"Un plan de conversación debe poder ___ cuando aparezca información nueva.","resp":["adaptarse"],"explica":"Relaciona este concepto con la decisión que acabas de analizar."}]},{"tipo":"reflexion","rotulo":"Práctica aplicada · 20 minutos orientativos","pregunta":"Completa una hoja de preparación para una propuesta ficticia. Incluye una condición que te haría retirar o cambiar la recomendación.","ayuda":"Primera versión, contraste con el modelo y revisión propia."},{"tipo":"texto","texto":"<details><summary>Consultar modelo y retroalimentación</summary><p>Modelo: no recomendar un curso autogestivo si la necesidad principal es supervisión individual continua. Tener una condición de no encaje evita convertir toda conversación en una venta forzada.</p><p>Compara tu respuesta: identifica una condición explícita, una afirmación que necesita respaldo y una mejora concreta. El modelo es una posibilidad, no la única respuesta válida.</p></details>"}],"minutosEstimados":45},{"id":"pe-m10-l2","titulo":"Simular preguntas difíciles","objetivo":"Aplicar simular preguntas difíciles mediante un caso, una decisión comentada y una producción propia.","bloques":[{"tipo":"texto","texto":"<p>Una simulación permite practicar sin exponer a terceros a una decisión real. Elige una pregunta que cuestione tu mejor argumento, no sólo dudas fáciles. Incluye costo, alcance, evidencia, riesgos y una comparación desfavorable.</p><p>Responde en tres pasos: reconocer la pregunta, contestar lo que sabes y señalar lo que debes comprobar. Si desconoces un dato, no llenes el silencio con una cifra inventada. Puedes decir cuándo podrías responder si tienes capacidad de investigarlo.</p><p>Después del ensayo, revisa si contestaste la pregunta real o cambiaste de tema. Una respuesta larga puede ser evasiva. Pide una reformulación de lo entendido o evalúa tu grabación privada con una lista de criterios. La simulación no prueba que una intervención real funcionará, pero ayuda a detectar vacíos antes de comprometerte.</p>"},{"tipo":"destacado","texto":"Caso ficticio: preguntan cuántos alumnos mejoraron su desempeño y no tienes medición de ese resultado."},{"tipo":"practica","rotulo":"Decide y contrasta","preguntas":[{"p":"¿Qué respuesta corresponde?","ops":["Inventar una proporción aproximada.","Responder con número de inscritos como si fuera mejora de desempeño.","Reconocer que no se midió ese resultado y explicar qué información sí está disponible."],"correcta":2,"explica":"Inscripción y desempeño son variables distintas. Reconocer la falta de medición evita convertir una cifra disponible en evidencia de otra cosa.","pista":"Revisa la restricción del caso y el efecto de tu respuesta sobre la decisión de la otra persona."}]},{"tipo":"completar","rotulo":"Recupera la idea clave","items":[{"frase":"Si no tienes un dato, debes reconocer la ___ en lugar de inventarlo.","resp":["incertidumbre"],"explica":"Relaciona este concepto con la decisión que acabas de analizar."}]},{"tipo":"reflexion","rotulo":"Práctica aplicada · 20 minutos orientativos","pregunta":"Escribe cinco preguntas difíciles y respuestas de hasta 80 palabras. Marca una que requiera investigación y una que obligue a limitar tu promesa.","ayuda":"Primera versión, contraste con el modelo y revisión propia."},{"tipo":"texto","texto":"<details><summary>Consultar modelo y retroalimentación</summary><p>Modelo: «No contamos con seguimiento de ventas. Sí evaluamos resolución de casos al terminar cada módulo». Esa respuesta diferencia el aprendizaje evaluado de un resultado laboral no medido.</p><p>Compara tu respuesta: identifica una condición explícita, una afirmación que necesita respaldo y una mejora concreta. El modelo es una posibilidad, no la única respuesta válida.</p></details>"},{"tipo":"relacionar","rotulo":"Relaciona el concepto con su aplicación","voz":false,"pares":[["Diagnóstico","Definir audiencia, decisión y restricciones"],["Indicador","Contar cuántas personas comprendieron las condiciones"],["Confusor","Cambiar al mismo tiempo la herramienta y el horario"],["Transferencia","Adaptar lo aprendido a una situación distinta"]]},{"tipo":"texto","texto":"<p><strong>Contrasta tu razonamiento:</strong> después de relacionar, explica por qué cada ejemplo corresponde a ese concepto y escribe un contraejemplo. No basta memorizar la pareja: identifica la conducta observable que la distingue.</p>"}],"minutosEstimados":45},{"id":"pe-m10-l3","titulo":"Medir resultados sin exagerar","objetivo":"Aplicar medir resultados sin exagerar mediante un caso, una decisión comentada y una producción propia.","bloques":[{"tipo":"texto","texto":"<p>Define qué significa mejorar antes de intervenir. Puedes medir comprensión, calidad del argumento, reducción de dudas o cumplimiento de un acuerdo. No midas sólo aceptación: una decisión informada de no comprar también puede reflejar buena comunicación.</p><p>Registra una referencia inicial, un criterio y un periodo. Si comparas versiones de un mensaje, considera diferencias de audiencia y contexto. Un aumento de respuestas no demuestra automáticamente que la nueva redacción fue la causa.</p><p>Combina indicadores con observaciones cualitativas y conserva resultados desfavorables. Explica limitaciones, tamaño de muestra y qué no se evaluó. Evita recopilar datos personales innecesarios para la práctica. Puedes trabajar con escenarios simulados, pero no anunciar sus resultados como impacto real del programa.</p>"},{"tipo":"destacado","texto":"Caso ficticio: envías dos mensajes a grupos distintos; uno recibe más respuestas."},{"tipo":"practica","rotulo":"Decide y contrasta","preguntas":[{"p":"¿Qué precaución es necesaria?","ops":["Eliminar del reporte al grupo con menor respuesta.","Considerar diferencias de audiencia y condiciones antes de atribuir el cambio al texto.","Afirmar causalidad sólo porque un grupo respondió más."],"correcta":1,"explica":"Los grupos pueden diferir en interés o disponibilidad. Reportar ambos resultados y sus límites permite una interpretación más honesta.","pista":"Revisa la restricción del caso y el efecto de tu respuesta sobre la decisión de la otra persona."}]},{"tipo":"completar","rotulo":"Recupera la idea clave","items":[{"frase":"Para evaluar un cambio conviene definir una referencia ___.","resp":["inicial"],"explica":"Relaciona este concepto con la decisión que acabas de analizar."}]},{"tipo":"reflexion","rotulo":"Práctica aplicada · 20 minutos orientativos","pregunta":"Diseña un registro con indicador, referencia, periodo, dato esperado y explicación alternativa. No uses datos personales reales de alumnos.","ayuda":"Primera versión, contraste con el modelo y revisión propia."},{"tipo":"texto","texto":"<details><summary>Consultar modelo y retroalimentación</summary><p>Modelo: medir si cinco lectores ficticios identifican costo, alcance y siguiente paso en una propuesta. Esto evalúa claridad del mensaje, no ventas ni cambios duraderos de conducta.</p><p>Compara tu respuesta: identifica una condición explícita, una afirmación que necesita respaldo y una mejora concreta. El modelo es una posibilidad, no la única respuesta válida.</p></details>"}],"minutosEstimados":45},{"id":"pe-m10-l4","titulo":"Revisar, transferir y cerrar el proyecto","objetivo":"Aplicar revisar, transferir y cerrar el proyecto mediante un caso, una decisión comentada y una producción propia.","bloques":[{"tipo":"texto","texto":"<p>Transferir una habilidad implica reconocer qué principio se mantiene y qué debe cambiar en un contexto nuevo. Un correo laboral y una invitación comunitaria pueden compartir claridad y transparencia, pero tener restricciones, lenguaje y procesos de decisión diferentes.</p><p>Revisa tu proyecto con cinco dimensiones: audiencia, evidencia, claridad, objeciones y autonomía. Usa ejemplos concretos de tu trabajo para justificar cada valoración. Una suma alta no compensa un dato falso o una condición importante oculta; corrige esos problemas antes de considerar la propuesta lista.</p><p>Termina con una nueva versión y un plan de práctica. Elige una habilidad observable, una ocasión realista para practicar y una forma de revisar el resultado. La autoevaluación es una herramienta de aprendizaje, no una certificación externa de calidad. Conserva las versiones para poder explicar cómo cambió tu razonamiento.</p>"},{"tipo":"destacado","texto":"Caso ficticio: tu rúbrica suma muchos puntos, pero descubres que una estadística no tiene fuente."},{"tipo":"practica","rotulo":"Decide y contrasta","preguntas":[{"p":"¿Qué debes hacer?","ops":["Retirar o verificar la estadística y revisar la conclusión, aunque la suma sea alta.","Conservarla porque los demás criterios compensan el problema.","Cambiar el número para que nadie lo cuestione."],"correcta":0,"explica":"Una puntuación agregada no legitima evidencia inventada. La revisión debe corregir problemas sustantivos, no sólo mejorar la calificación.","pista":"Revisa la restricción del caso y el efecto de tu respuesta sobre la decisión de la otra persona."}]},{"tipo":"completar","rotulo":"Recupera la idea clave","items":[{"frase":"La autoevaluación no sustituye una revisión ___ de calidad.","resp":["externa"],"explica":"Relaciona este concepto con la decisión que acabas de analizar."}]},{"tipo":"reflexion","rotulo":"Práctica aplicada · 20 minutos orientativos","pregunta":"Entrega tu proyecto con versión inicial, versión final y comentario de 300 palabras sobre tres cambios. Añade un plan de práctica para dos semanas.","ayuda":"Primera versión, contraste con el modelo y revisión propia."},{"tipo":"texto","texto":"<details><summary>Consultar modelo y retroalimentación</summary><p>Modelo: cambiar una garantía por un resultado observable, añadir costo total y preparar una respuesta que acepte un no. Explica qué información provocó cada cambio y qué incertidumbre permanece.</p><p>Compara tu respuesta: identifica una condición explícita, una afirmación que necesita respaldo y una mejora concreta. El modelo es una posibilidad, no la única respuesta válida.</p></details>"},{"tipo":"texto","texto":"<h3>Reto del módulo · 90 minutos orientativos</h3><p>Audita una propuesta completa ajena o ficticia con la rúbrica antes de evaluar la tuya. Entrega una versión corregida y una explicación de qué evidencia todavía falta.</p><p><strong>Entregable:</strong> Auditoría, propuesta final, guion, objeciones y plan de seguimiento.</p><p>Diagnóstico 15 min; primera versión 30; contraste 20; revisión 15; reflexión 10.</p>"},{"tipo":"reflexion","rotulo":"Bitácora del reto","pregunta":"Registra tu primera versión, una condición que faltaba y tu revisión justificada."},{"tipo":"texto","texto":"<h3>Autoevaluación del reto</h3><p>Revisa decisión clara, evidencia pertinente, condiciones explícitas y respeto al rechazo. En cada criterio: 0 ausente; 1 genérico; 2 concreto y justificado. Corrige los criterios con 0. Usa los modelos de las cuatro lecciones para contrastar tus decisiones.</p>"},{"tipo":"texto","texto":"<h3>Proyecto integrador · 10 horas estimadas</h3><p>Prepara una propuesta real o ficticia de 700–1,000 palabras, una exposición de tres minutos y respuestas a cuatro objeciones. Conserva primera versión, revisión y justificación de tres cambios.</p><p>Diagnóstico 90 min; evidencia 120; propuesta 120; exposición y objeciones 90; autoevaluación 60; revisión 120.</p><p>Rúbrica: audiencia 20%, evidencia 25%, claridad 20%, objeciones 20%, autonomía y transparencia 15%. Nivel 0: ausente; 1: genérico o incompleto; 2: concreto y suficiente; 3: justificado con evidencia y límites. Puntaje orientativo = suma de nivel / 3 × peso. Es una autoevaluación; no califica automáticamente la calidad del trabajo. Consulta el cuaderno para los descriptores completos.</p>"},{"tipo":"reflexion","rotulo":"Síntesis del proyecto","pregunta":"Describe tu propuesta, la evidencia por criterio, tres cambios justificados y lo que falta comprobar."}],"minutosEstimados":45}],"quiz":{"titulo":"Evaluación de aplicación","preguntas":[{"p":"Una propuesta integra un resultado ambicioso sin datos. ¿Qué cambiarías primero?","ops":["Calibrar la promesa y explicar cómo se evaluará.","Mejorar únicamente el diseño.","Añadir un testimonio ficticio como real."],"correcta":0,"explica":"La promesa debe corresponder al respaldo disponible."},{"p":"¿Qué plan de preparación es más completo?","ops":["Memorizar sólo la primera frase.","Preparar un cierre agresivo.","Definir audiencia, decisión, evidencia, límites y objeciones."],"correcta":2,"explica":"Preparar los componentes de decisión permite adaptar la conversación."},{"p":"Durante una exposición aparece una pregunta sin respuesta comprobada. ¿Qué haces?","ops":["Descalificas la pregunta.","Reconoces el límite y acuerdas cómo verificarla.","Inventas un dato para mantener ritmo."],"correcta":1,"explica":"Gestionar incertidumbre conserva precisión y permite seguimiento."},{"p":"Una campaña consigue muchos clics pero genera confusión sobre el precio. ¿Cómo evaluarla?","ops":["Medir también comprensión y decisiones informadas.","Declararla exitosa sólo por clics.","Eliminar el precio para conseguir más clics."],"correcta":0,"explica":"La atención no basta si la comprensión de condiciones falla."},{"p":"Dos versiones se prueban en públicos diferentes. ¿Qué limita la comparación?","ops":["Nada, cualquier comparación prueba causalidad.","Sólo el tamaño del título.","No puedes atribuir con seguridad la diferencia sólo al mensaje."],"correcta":2,"explica":"Las diferencias de audiencia pueden explicar parte del resultado."},{"p":"¿Qué evidencia sirve para autoevaluar el proyecto?","ops":["El número de palabras del texto.","Mensaje, fuentes, condiciones, respuestas a objeciones y revisión documentada.","Sólo la sensación de seguridad."],"correcta":1,"explica":"La rúbrica necesita evidencias observables para cada criterio."},{"p":"Una revisión detecta una condición importante omitida. ¿Qué harías?","ops":["Corregirla antes de usar la propuesta y registrar el cambio.","Mantenerla si mejora la conversión.","Ocultarla en una imagen ilegible."],"correcta":0,"explica":"La transparencia exige corregir omisiones que afectan la decisión."},{"p":"¿Qué meta de transferencia es comprobable?","ops":["Ser influyente para siempre.","No recibir nunca objeciones.","Aplicar la estructura a dos propuestas y revisar comprensión en dos semanas."],"correcta":2,"explica":"Una meta concreta permite practicar y observar resultados."},{"p":"¿Qué significa aprobar un cuestionario de este diplomado?","ops":["Garantizar éxito comercial en cualquier contexto.","Superar una comprobación de conocimientos según su umbral.","Demostrar dominio profesional universal."],"correcta":1,"explica":"Una evaluación tiene alcance limitado; la transferencia requiere práctica."},{"p":"¿Cuál cierre del proyecto es más sólido?","ops":["Explicar qué cambió, qué evidencia lo motivó y qué sigue incierto.","Afirmar que el mensaje ya es perfecto.","Excluir las críticas de la reflexión final."],"correcta":0,"explica":"Documentar decisiones y límites permite seguir aprendiendo."}]}}]});
